export const questions: Question[] = [
  { id: "y2in4-001", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 01", difficulty: "Standard", questionText: "Find \\[ \\int \\displaystyle\\frac{x}{x^2 + 1}\\,dx \\]", marks: 3, examStyle: false, yearCreated: 2026, tags: ["reverse chain", "logarithm"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{f'(x)}{f(x)}\\,dx = \\ln|f(x)| + C", explanation: "The reverse-chain logarithm pattern. Whenever the numerator of a quotient is (a constant multiple of) the derivative of the denominator, the antiderivative is a logarithm of the denominator. It comes from undoing \\(\\displaystyle\\frac{d}{dx}\\ln|f(x)| = \\displaystyle\\frac{f'(x)}{f(x)}\\)." }, { stepNumber: 2, description: "Why this rule fits here.", workingLatex: "\\text{Integrand} = \\displaystyle\\frac{x}{x^2 + 1} \\;\\;\\text{— quotient with quadratic denominator and linear numerator.}", explanation: "The denominator is a function of \\(x\\) and the numerator looks like it might be (a multiple of) its derivative. That is exactly the \\(f'/f\\) template — so the antiderivative will be a logarithm, not a power or an arctan." }, { stepNumber: 3, description: "Identify \\(f\\) and differentiate it.", workingLatex: "f(x) = x^2 + 1 \\;\\Rightarrow\\; f'(x) = 2x", explanation: "Take the denominator as \\(f\\); we now know exactly what \\(f'(x)\\) needs to be in the numerator for the rule to apply directly." }, { stepNumber: 4, description: "Compare numerator to \\(f'(x)\\).", workingLatex: "\\text{Numerator } x = \\displaystyle\\frac{1}{2}\\,f'(x) \\;\\;\\Rightarrow\\;\\; \\text{integrand} = \\displaystyle\\frac{1}{2}\\cdot\\displaystyle\\frac{f'(x)}{f(x)}", explanation: "The numerator is \\(x\\) but we need \\(2x\\). We are short by a factor of \\(2\\) — equivalently, the integrand is \\(\\displaystyle\\frac{1}{2}\\) times the rule's template." }, { stepNumber: 5, description: "Pull out the \\(\\displaystyle\\frac{1}{2}\\) using linearity.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{x}{x^2 + 1}\\,dx = \\displaystyle\\frac{1}{2}\\displaystyle\\int \\displaystyle\\frac{2x}{x^2 + 1}\\,dx", explanation: "Multiplying the integrand by \\(2\\) and compensating with an outer \\(\\displaystyle\\frac{1}{2}\\) lines the numerator up exactly with \\(f'(x)\\). Linearity (constants factor out of integrals) makes this valid." }, { stepNumber: 6, description: "Apply the rule to the bracketed integral.", workingLatex: "= \\displaystyle\\frac{1}{2}\\ln|x^2 + 1| + C", explanation: "The integrand inside is now exactly \\(f'/f\\), so the antiderivative is \\(\\ln|f|\\) — the leading \\(\\displaystyle\\frac{1}{2}\\) just rides along." }, { stepNumber: 7, description: "Drop the modulus bars.", workingLatex: "= \\displaystyle\\frac{1}{2}\\ln(x^2 + 1) + C", explanation: "Since \\(x^2 + 1 \\ge 1 > 0\\) for every real \\(x\\), the argument of the log is always positive and the bars are redundant." }, { stepNumber: 8, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{1}{2}\\ln(x^2 + 1)\\right] = \\displaystyle\\frac{1}{2}\\cdot\\displaystyle\\frac{2x}{x^2 + 1} = \\displaystyle\\frac{x}{x^2 + 1}\\;\\checkmark", explanation: "Differentiating back recovers the original integrand exactly — the antiderivative is correct." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{2}\\ln(x^2 + 1) + C\\)." } },
  // ── \\displaystyle\\int f'/f = \\ln|f| ────
  { id: "y2in4-002", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 02", difficulty: "Foundation", questionText: "Find \\[ \\int \\displaystyle\\frac{2x}{x^2 + 3}\\,dx \\]", marks: 2, examStyle: false, yearCreated: 2026, tags: ["reverse chain", "log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{f'(x)}{f(x)}\\,dx = \\ln|f(x)| + C", explanation: "The reverse-chain log rule: when a quotient has the derivative of the denominator sitting on top, the antiderivative is the natural log of the denominator." }, { stepNumber: 2, description: "Identify the inner function \\(f\\).", workingLatex: "f(x) = x^2 + 3", explanation: "The denominator is the natural choice of \\(f\\): the rule expects the denominator to be the function whose derivative appears on top." }, { stepNumber: 3, description: "Differentiate \\(f\\).", workingLatex: "f'(x) = 2x", explanation: "Power rule: \\(\\displaystyle\\frac{d}{dx}(x^2) = 2x\\); the constant \\(3\\) differentiates to zero." }, { stepNumber: 4, description: "Compare numerator to \\(f'(x)\\).", workingLatex: "\\text{Numerator } 2x = f'(x)", explanation: "The numerator matches \\(f'(x)\\) exactly — no constant adjustment is needed." }, { stepNumber: 5, description: "Apply the rule directly.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{2x}{x^2 + 3}\\,dx = \\ln|x^2 + 3| + C = \\ln(x^2 + 3) + C", explanation: "Because \\(x^2 + 3 \\ge 3 > 0\\) always, the modulus bars are redundant and can be dropped." } ], finalAnswer: "\\(\\ln(x^2 + 3) + C\\)." } },
  { id: "y2in4-003", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 03", difficulty: "Foundation", questionText: "Find \\[ \\int \\displaystyle\\frac{3x^2}{x^3 + 1}\\,dx \\]", marks: 2, examStyle: false, yearCreated: 2026, tags: ["reverse chain", "log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{f'(x)}{f(x)}\\,dx = \\ln|f(x)| + C", explanation: "The reverse-chain log rule. It applies whenever the numerator is exactly (a constant multiple of) the derivative of the denominator." }, { stepNumber: 2, description: "Identify the inner function \\(f\\).", workingLatex: "f(x) = x^3 + 1", explanation: "Take the denominator as \\(f\\) and check whether its derivative is in the numerator." }, { stepNumber: 3, description: "Differentiate \\(f\\).", workingLatex: "f'(x) = 3x^2", explanation: "Power rule again; the \\(+1\\) drops out." }, { stepNumber: 4, description: "Compare numerator to \\(f'(x)\\).", workingLatex: "\\text{Numerator } 3x^2 = f'(x)", explanation: "Exact match — the integrand is already in clean \\(f'/f\\) form, so no rescaling is required." }, { stepNumber: 5, description: "Apply the rule.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{3x^2}{x^3 + 1}\\,dx = \\ln|x^3 + 1| + C", explanation: "Keep the modulus bars: \\(x^3 + 1 = (x+1)(x^2 - x + 1)\\) changes sign at \\(x = -1\\), so the argument is sometimes negative." } ], finalAnswer: "\\(\\ln|x^3 + 1| + C\\)." } },
  { id: "y2in4-004", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 04", difficulty: "Foundation", questionText: "Find \\[ \\int \\displaystyle\\frac{\\cos x}{\\sin x}\\,dx \\]", marks: 2, examStyle: false, yearCreated: 2026, tags: ["log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{f'(x)}{f(x)}\\,dx = \\ln|f(x)| + C", explanation: "Reverse-chain log pattern. The integrand is the derivative of \\(\\ln|f|\\), so we recover \\(\\ln|f|\\) by going backwards." }, { stepNumber: 2, description: "Identify \\(f\\).", workingLatex: "f(x) = \\sin x", explanation: "Pick the denominator as \\(f\\); the question is then whether its derivative sits on top." }, { stepNumber: 3, description: "Differentiate \\(f\\).", workingLatex: "f'(x) = \\cos x", explanation: "Standard derivative: \\(\\displaystyle\\frac{d}{dx}\\sin x = \\cos x\\)." }, { stepNumber: 4, description: "Compare numerator to \\(f'(x)\\).", workingLatex: "\\text{Numerator } \\cos x = f'(x)", explanation: "Textbook \\(f'/f\\) set-up — no constant adjustment needed." }, { stepNumber: 5, description: "Apply the rule.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{\\cos x}{\\sin x}\\,dx = \\ln|\\sin x| + C", explanation: "Keep modulus bars: \\(\\sin x\\) is negative on \\((\\pi, 2\\pi)\\) and elsewhere, so the antiderivative is only defined where \\(\\sin x \\neq 0\\)." } ], finalAnswer: "\\(\\ln|\\sin x| + C\\)." } },
  { id: "y2in4-005", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 05", difficulty: "Foundation", questionText: "Find \\[ \\int \\displaystyle\\frac{-\\sin x}{\\cos x}\\,dx \\]", marks: 2, examStyle: false, yearCreated: 2026, tags: ["log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{f'(x)}{f(x)}\\,dx = \\ln|f(x)| + C", explanation: "Reverse-chain log rule. We expect the numerator to be the derivative of the denominator — including any negative sign." }, { stepNumber: 2, description: "Identify \\(f\\).", workingLatex: "f(x) = \\cos x", explanation: "Denominator as \\(f\\); the key question is what its derivative looks like." }, { stepNumber: 3, description: "Differentiate \\(f\\).", workingLatex: "f'(x) = -\\sin x", explanation: "Standard derivative: \\(\\displaystyle\\frac{d}{dx}\\cos x = -\\sin x\\). The minus sign is part of the derivative — it isn't a sign error to track." }, { stepNumber: 4, description: "Compare numerator to \\(f'(x)\\).", workingLatex: "\\text{Numerator } -\\sin x = f'(x)", explanation: "The numerator is exactly \\(f'(x)\\) — including the minus. So the integrand is in clean \\(f'/f\\) form." }, { stepNumber: 5, description: "Apply the rule.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{-\\sin x}{\\cos x}\\,dx = \\ln|\\cos x| + C", explanation: "Modulus bars are essential: \\(\\cos x < 0\\) on \\((\\pi/2, 3\\pi/2)\\), so writing \\(\\ln(\\cos x)\\) would be undefined there." } ], finalAnswer: "\\(\\ln|\\cos x| + C\\)." } },
  { id: "y2in4-006", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 06", difficulty: "Standard", questionText: "Find \\[ \\int \\displaystyle\\frac{e^x}{e^x + 1}\\,dx \\]", marks: 2, examStyle: false, yearCreated: 2026, tags: ["log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{f'(x)}{f(x)}\\,dx = \\ln|f(x)| + C", explanation: "Reverse-chain log pattern. We are looking for the numerator to be the derivative of the denominator." }, { stepNumber: 2, description: "Identify \\(f\\).", workingLatex: "f(x) = e^x + 1", explanation: "Denominator as \\(f\\) — the natural reflex for \\(f'/f\\) spotting." }, { stepNumber: 3, description: "Differentiate \\(f\\).", workingLatex: "f'(x) = e^x", explanation: "\\(\\displaystyle\\frac{d}{dx}e^x = e^x\\); the constant \\(1\\) drops out." }, { stepNumber: 4, description: "Compare numerator to \\(f'(x)\\).", workingLatex: "\\text{Numerator } e^x = f'(x)", explanation: "Exact match — no constant adjustment needed." }, { stepNumber: 5, description: "Apply the rule.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{e^x}{e^x + 1}\\,dx = \\ln|e^x + 1| + C", explanation: "Direct rule application — the integrand is exactly \\(f'/f\\)." }, { stepNumber: 6, description: "Drop the modulus bars.", workingLatex: "= \\ln(e^x + 1) + C", explanation: "\\(e^x > 0\\) for all real \\(x\\), so \\(e^x + 1 > 1 > 0\\); the bars are redundant." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\ln(e^x + 1) = \\displaystyle\\frac{e^x}{e^x + 1}\\;\\checkmark", explanation: "Recovers the integrand — the antiderivative is correct." } ], finalAnswer: "\\(\\ln(e^x + 1) + C\\)." } },
  { id: "y2in4-007", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 07", difficulty: "Challenge", questionText: "Find \\[ \\int \\displaystyle\\frac{1}{x\\ln x}\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int F(g(x))\\,g'(x)\\,dx = \\displaystyle\\int F(u)\\,du", explanation: "The standard \\(u\\)-substitution template — reversing the chain rule. We will use it to recognise that \\(\\ln x\\) and \\(\\displaystyle\\frac{1}{x}\\,dx\\) together are exactly a \\(u\\)-and-\\(du\\) pair." }, { stepNumber: 2, description: "Why u-sub here.", workingLatex: "\\text{Spot: } \\ln x \\text{ in the integrand and its derivative } \\displaystyle\\frac{1}{x} \\text{ as a factor of } dx.", explanation: "The function \\(\\ln x\\) appears, and so does its derivative \\(\\displaystyle\\frac{1}{x}\\). That function-and-derivative pairing is the standard cue for substitution — the cleanest way to collapse the nested log." }, { stepNumber: 3, description: "Choose \\(u\\).", workingLatex: "u = \\ln x", explanation: "Picking \\(u\\) as the inner composite function (the \\(\\ln x\\) inside the denominator) is the natural choice." }, { stepNumber: 4, description: "Compute \\(du\\).", workingLatex: "du = \\displaystyle\\frac{1}{x}\\,dx", explanation: "Standard derivative of \\(\\ln x\\). Notice that \\(\\displaystyle\\frac{dx}{x}\\) is already sitting inside the integrand, ready to become \\(du\\)." }, { stepNumber: 5, description: "Rewrite the integral entirely in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{1}{x\\ln x}\\,dx = \\displaystyle\\int \\displaystyle\\frac{1}{\\ln x}\\cdot\\displaystyle\\frac{1}{x}\\,dx = \\displaystyle\\int \\displaystyle\\frac{1}{u}\\,du", explanation: "Replace \\(\\ln x \\to u\\) and \\(\\displaystyle\\frac{1}{x}\\,dx \\to du\\). The whole nested structure collapses to the simplest possible log integral." }, { stepNumber: 6, description: "Integrate in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{1}{u}\\,du = \\ln|u| + C", explanation: "Standard antiderivative — this is exactly the reverse of \\(\\displaystyle\\frac{d}{du}\\ln|u| = \\displaystyle\\frac{1}{u}\\)." }, { stepNumber: 7, description: "Back-substitute \\(u = \\ln x\\).", workingLatex: "= \\ln|\\ln x| + C", explanation: "Replace \\(u\\) with its definition. Modulus bars matter — \\(\\ln x < 0\\) for \\(0 < x < 1\\), so \\(\\ln|\\ln x|\\) without bars would be undefined there." }, { stepNumber: 8, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\ln|\\ln x| = \\displaystyle\\frac{1}{\\ln x}\\cdot\\displaystyle\\frac{1}{x} = \\displaystyle\\frac{1}{x\\ln x}\\;\\checkmark", explanation: "Two nested chain-rule applications recover the integrand exactly — the antiderivative is verified." } ], finalAnswer: "\\(\\ln|\\ln x| + C\\)." } },
  { id: "y2in4-008", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 08", difficulty: "Standard", questionText: "Find \\[ \\int \\displaystyle\\frac{2x + 3}{x^2 + 3x - 1}\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{f'(x)}{f(x)}\\,dx = \\ln|f(x)| + C", explanation: "Reverse-chain log rule. Triggered when a quotient has the derivative of the denominator sitting in the numerator." }, { stepNumber: 2, description: "Identify \\(f\\).", workingLatex: "f(x) = x^2 + 3x - 1", explanation: "Denominator as \\(f\\) — the standard reflex for this rule." }, { stepNumber: 3, description: "Differentiate \\(f\\).", workingLatex: "f'(x) = 2x + 3", explanation: "Term-by-term: \\(\\displaystyle\\frac{d}{dx}(x^2) = 2x\\), \\(\\displaystyle\\frac{d}{dx}(3x) = 3\\), \\(\\displaystyle\\frac{d}{dx}(-1) = 0\\)." }, { stepNumber: 4, description: "Compare numerator to \\(f'(x)\\).", workingLatex: "\\text{Numerator } 2x + 3 = f'(x)", explanation: "Exact match — the integrand is already in clean \\(f'/f\\) form with no constant adjustment needed." }, { stepNumber: 5, description: "Apply the rule.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{2x + 3}{x^2 + 3x - 1}\\,dx = \\ln|x^2 + 3x - 1| + C", explanation: "The quadratic has discriminant \\(9 + 4 = 13 > 0\\), so it has real roots and changes sign — modulus bars are required." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\ln|x^2 + 3x - 1| = \\displaystyle\\frac{2x + 3}{x^2 + 3x - 1}\\;\\checkmark", explanation: "Differentiating back recovers the integrand." } ], finalAnswer: "\\(\\ln|x^2 + 3x - 1| + C\\)." } },
  { id: "y2in4-009", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 09", difficulty: "Standard", questionText: "Find \\[ \\int \\displaystyle\\frac{x - 2}{x^2 - 4x + 5}\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{f'(x)}{f(x)}\\,dx = \\ln|f(x)| + C", explanation: "Reverse-chain log pattern." }, { stepNumber: 2, description: "Identify \\(f\\).", workingLatex: "f(x) = x^2 - 4x + 5", explanation: "Denominator as \\(f\\)." }, { stepNumber: 3, description: "Differentiate \\(f\\).", workingLatex: "f'(x) = 2x - 4 = 2(x - 2)", explanation: "Factor out the \\(2\\) — this makes the comparison with the numerator transparent." }, { stepNumber: 4, description: "Compare numerator to \\(f'(x)\\).", workingLatex: "\\text{Numerator } x - 2 = \\displaystyle\\frac{1}{2}\\,f'(x)", explanation: "We are short by a factor of \\(2\\) — need a compensating \\(\\displaystyle\\frac{1}{2}\\) outside." }, { stepNumber: 5, description: "Pull out the \\(\\displaystyle\\frac{1}{2}\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{x - 2}{x^2 - 4x + 5}\\,dx = \\displaystyle\\frac{1}{2}\\displaystyle\\int \\displaystyle\\frac{2(x - 2)}{x^2 - 4x + 5}\\,dx", explanation: "Now the numerator is exactly \\(2(x - 2) = f'(x)\\), so the bracketed integral is in clean \\(f'/f\\) form." }, { stepNumber: 6, description: "Apply the rule.", workingLatex: "= \\displaystyle\\frac{1}{2}\\ln|x^2 - 4x + 5| + C", explanation: "The bracketed integral gives \\(\\ln|f|\\); the \\(\\displaystyle\\frac{1}{2}\\) rides along." }, { stepNumber: 7, description: "Note on modulus bars.", workingLatex: "x^2 - 4x + 5 = (x - 2)^2 + 1 \\ge 1 > 0", explanation: "Completing the square shows the quadratic is always positive, so the bars are optional. We keep them by convention." }, { stepNumber: 8, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{1}{2}\\ln|x^2 - 4x + 5|\\right] = \\displaystyle\\frac{1}{2}\\cdot\\displaystyle\\frac{2x - 4}{x^2 - 4x + 5} = \\displaystyle\\frac{x - 2}{x^2 - 4x + 5}\\;\\checkmark", explanation: "Confirms the antiderivative." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{2}\\ln|x^2 - 4x + 5| + C\\)." } },
  { id: "y2in4-010", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 10", difficulty: "Standard", questionText: "Find \\[ \\int \\tan x\\,dx \\]", marks: 2, examStyle: false, yearCreated: 2026, tags: ["log"], workedSolution: { steps: [ { stepNumber: 1, description: "Why we need an identity first.", workingLatex: "\\tan x \\text{ has no obvious } f'/f \\text{ form as written.}", explanation: "\\(\\tan x\\) is not on the standard antiderivative list. We need to rewrite it in a form the reverse-chain rule can act on — splitting it back into \\(\\sin/\\cos\\) does the job." }, { stepNumber: 2, description: "Rewrite \\(\\tan x\\) as a quotient.", workingLatex: "\\tan x = \\displaystyle\\frac{\\sin x}{\\cos x}", explanation: "Definition of tangent. Now the integrand is a quotient — exactly the shape the \\(f'/f\\) rule expects." }, { stepNumber: 3, description: "State the rule used.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{f'(x)}{f(x)}\\,dx = \\ln|f(x)| + C", explanation: "Reverse-chain log pattern." }, { stepNumber: 4, description: "Identify \\(f\\) and differentiate it.", workingLatex: "f(x) = \\cos x \\;\\Rightarrow\\; f'(x) = -\\sin x", explanation: "Denominator as \\(f\\); its derivative carries a minus sign — we must account for it." }, { stepNumber: 5, description: "Compare numerator to \\(f'(x)\\) and rewrite with a leading minus.", workingLatex: "\\displaystyle\\int \\tan x\\,dx = \\displaystyle\\int \\displaystyle\\frac{\\sin x}{\\cos x}\\,dx = -\\displaystyle\\int \\displaystyle\\frac{-\\sin x}{\\cos x}\\,dx", explanation: "The numerator \\(\\sin x\\) is \\(-f'(x)\\); inserting two minus signs (one inside, one out) lines up the integrand with the rule template." }, { stepNumber: 6, description: "Apply the rule.", workingLatex: "= -\\ln|\\cos x| + C", explanation: "The bracketed integral is now \\(f'/f\\), giving \\(\\ln|f|\\); the outer minus stays." }, { stepNumber: 7, description: "Rewrite using \\(\\sec x\\).", workingLatex: "-\\ln|\\cos x| + C = \\ln\\!\\left|\\displaystyle\\frac{1}{\\cos x}\\right| + C = \\ln|\\sec x| + C", explanation: "Using \\(\\ln(1/a) = -\\ln a\\) and \\(1/\\cos x = \\sec x\\). Both forms are accepted; \\(\\ln|\\sec x|\\) is the canonical answer in the formula book." }, { stepNumber: 8, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\ln|\\sec x| = \\displaystyle\\frac{\\sec x\\tan x}{\\sec x} = \\tan x\\;\\checkmark", explanation: "Using \\(\\displaystyle\\frac{d}{dx}\\sec x = \\sec x\\tan x\\); recovers the integrand." } ], finalAnswer: "\\(\\ln|\\sec x| + C\\)." } },
  // ── \\displaystyle\\int f'(x)[f(x)]^n ────
  { id: "y2in4-011", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 11", difficulty: "Standard", questionText: "Find \\[ \\int x(x^2 + 1)^3\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["reverse chain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int f'(x)\\bigl[f(x)\\bigr]^n\\,dx = \\displaystyle\\frac{\\bigl[f(x)\\bigr]^{n+1}}{n+1} + C", explanation: "The reverse-chain power rule: if the integrand is a power of \\(f\\) multiplied by its derivative, the antiderivative is the next power of \\(f\\), divided by the new index. It is the reverse of \\(\\displaystyle\\frac{d}{dx}[f]^{n+1} = (n+1)[f]^n f'\\)." }, { stepNumber: 2, description: "Why this rule fits here.", workingLatex: "\\text{Spot: power of } (x^2 + 1) \\text{ multiplied by something resembling its derivative.}", explanation: "Inside is \\(x^2 + 1\\) raised to a power; outside is \\(x\\), which is (a multiple of) the derivative \\(2x\\). That is the power-and-derivative pattern the rule expects." }, { stepNumber: 3, description: "Identify \\(f\\) and differentiate it.", workingLatex: "f(x) = x^2 + 1 \\;\\Rightarrow\\; f'(x) = 2x", explanation: "The inner function is the base of the power; its derivative tells us what factor we need to see outside." }, { stepNumber: 4, description: "Compare the co-factor to \\(f'(x)\\).", workingLatex: "\\text{Co-factor } x = \\displaystyle\\frac{1}{2}\\,f'(x)", explanation: "We have \\(x\\) but the rule wants \\(2x\\); we are short by a factor of \\(2\\)." }, { stepNumber: 5, description: "Pull out the \\(\\displaystyle\\frac{1}{2}\\).", workingLatex: "\\displaystyle\\int x(x^2 + 1)^3\\,dx = \\displaystyle\\frac{1}{2}\\displaystyle\\int 2x\\,(x^2 + 1)^3\\,dx", explanation: "Multiplying inside by \\(2\\) and compensating with \\(\\displaystyle\\frac{1}{2}\\) outside lines up the integrand exactly with \\(f'\\cdot f^n\\)." }, { stepNumber: 6, description: "Apply the rule with \\(n = 3\\).", workingLatex: "= \\displaystyle\\frac{1}{2}\\cdot\\displaystyle\\frac{(x^2 + 1)^4}{4} + C", explanation: "Raise the power by one to get index \\(4\\); divide by the new index." }, { stepNumber: 7, description: "Tidy.", workingLatex: "= \\displaystyle\\frac{(x^2 + 1)^4}{8} + C", explanation: "Combine the two halves: \\(\\displaystyle\\frac{1}{2}\\cdot\\displaystyle\\frac{1}{4} = \\displaystyle\\frac{1}{8}\\)." }, { stepNumber: 8, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{(x^2+1)^4}{8}\\right] = \\displaystyle\\frac{4(x^2+1)^3\\cdot 2x}{8} = x(x^2+1)^3\\;\\checkmark", explanation: "Recovers the integrand exactly — the answer is verified." } ], finalAnswer: "\\(\\displaystyle\\frac{(x^2 + 1)^4}{8} + C\\)." } },
  { id: "y2in4-012", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 12", difficulty: "Standard", questionText: "Find \\[ \\int 2x(x^2 - 5)^4\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["reverse chain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int f'(x)\\bigl[f(x)\\bigr]^n\\,dx = \\displaystyle\\frac{\\bigl[f(x)\\bigr]^{n+1}}{n+1} + C", explanation: "Reverse-chain power rule: a power of \\(f\\) multiplied by its derivative integrates to the next power of \\(f\\), divided by the new index." }, { stepNumber: 2, description: "Identify \\(f\\).", workingLatex: "f(x) = x^2 - 5", explanation: "The base of the power inside the bracket." }, { stepNumber: 3, description: "Differentiate \\(f\\).", workingLatex: "f'(x) = 2x", explanation: "Power rule; the constant \\(-5\\) drops out." }, { stepNumber: 4, description: "Compare the co-factor to \\(f'(x)\\).", workingLatex: "\\text{Co-factor } 2x = f'(x)", explanation: "Exact match — the integrand is already in clean \\(f'\\cdot f^n\\) form, no rescaling required." }, { stepNumber: 5, description: "Apply the rule with \\(n = 4\\).", workingLatex: "\\displaystyle\\int 2x(x^2 - 5)^4\\,dx = \\displaystyle\\frac{(x^2 - 5)^5}{5} + C", explanation: "Raise the index by one to \\(5\\); divide by \\(5\\)." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{(x^2 - 5)^5}{5}\\right] = \\displaystyle\\frac{5(x^2 - 5)^4\\cdot 2x}{5} = 2x(x^2 - 5)^4\\;\\checkmark", explanation: "Confirms the antiderivative." } ], finalAnswer: "\\(\\displaystyle\\frac{(x^2 - 5)^5}{5} + C\\)." } },
  { id: "y2in4-013", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 13", difficulty: "Standard", questionText: "Find \\[ \\int 3x^2\\left(x^3 + 4\\right)^5\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["reverse chain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int f'(x)\\bigl[f(x)\\bigr]^n\\,dx = \\displaystyle\\frac{\\bigl[f(x)\\bigr]^{n+1}}{n+1} + C", explanation: "Reverse-chain power rule." }, { stepNumber: 2, description: "Identify \\(f\\).", workingLatex: "f(x) = x^3 + 4", explanation: "Base of the power inside the bracket." }, { stepNumber: 3, description: "Differentiate \\(f\\).", workingLatex: "f'(x) = 3x^2", explanation: "Power rule on \\(x^3\\); the \\(+4\\) drops out." }, { stepNumber: 4, description: "Compare the co-factor to \\(f'(x)\\).", workingLatex: "\\text{Co-factor } 3x^2 = f'(x)", explanation: "Exact match — the integrand is already in clean \\(f'\\cdot f^n\\) form." }, { stepNumber: 5, description: "Apply the rule with \\(n = 5\\).", workingLatex: "\\displaystyle\\int 3x^2(x^3 + 4)^5\\,dx = \\displaystyle\\frac{(x^3 + 4)^6}{6} + C", explanation: "Raise the index by one to \\(6\\); divide by \\(6\\)." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{(x^3 + 4)^6}{6}\\right] = \\displaystyle\\frac{6(x^3 + 4)^5\\cdot 3x^2}{6} = 3x^2(x^3 + 4)^5\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{(x^3 + 4)^6}{6} + C\\)." } },
  { id: "y2in4-014", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 14", difficulty: "Standard", questionText: "Find \\[ \\int x\\sqrt{x^2 + 1}\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["reverse chain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int f'(x)\\bigl[f(x)\\bigr]^n\\,dx = \\displaystyle\\frac{\\bigl[f(x)\\bigr]^{n+1}}{n+1} + C", explanation: "Reverse-chain power rule. It works for any real \\(n \\neq -1\\), including \\(n = \\displaystyle\\frac{1}{2}\\) (the square-root case)." }, { stepNumber: 2, description: "Rewrite the surd as a fractional power.", workingLatex: "\\sqrt{x^2 + 1} = (x^2 + 1)^{\\frac{1}{2}}", explanation: "Surfaces the power-of-\\(f\\) structure the rule needs. Always do this conversion when a square root sits over an inner expression." }, { stepNumber: 3, description: "Identify \\(f\\) and differentiate it.", workingLatex: "f(x) = x^2 + 1 \\;\\Rightarrow\\; f'(x) = 2x", explanation: "Base of the power; its derivative is what we want to see outside." }, { stepNumber: 4, description: "Compare the co-factor to \\(f'(x)\\).", workingLatex: "\\text{Co-factor } x = \\displaystyle\\frac{1}{2}\\,f'(x)", explanation: "Short by a factor of \\(2\\) — need \\(\\displaystyle\\frac{1}{2}\\) outside." }, { stepNumber: 5, description: "Pull out the \\(\\displaystyle\\frac{1}{2}\\).", workingLatex: "\\displaystyle\\int x(x^2 + 1)^{\\frac{1}{2}}\\,dx = \\displaystyle\\frac{1}{2}\\displaystyle\\int 2x\\,(x^2 + 1)^{\\frac{1}{2}}\\,dx", explanation: "Brings the co-factor up to \\(f'(x)\\) exactly." }, { stepNumber: 6, description: "Apply the rule with \\(n = \\displaystyle\\frac{1}{2}\\).", workingLatex: "= \\displaystyle\\frac{1}{2}\\cdot\\displaystyle\\frac{(x^2 + 1)^{\\frac{3}{2}}}{3/2} + C", explanation: "New index is \\(\\displaystyle\\frac{1}{2} + 1 = \\displaystyle\\frac{3}{2}\\); divide by \\(\\displaystyle\\frac{3}{2}\\), i.e. multiply by \\(\\displaystyle\\frac{2}{3}\\)." }, { stepNumber: 7, description: "Tidy.", workingLatex: "= \\displaystyle\\frac{1}{2}\\cdot\\displaystyle\\frac{2}{3}(x^2 + 1)^{\\frac{3}{2}} + C = \\displaystyle\\frac{(x^2 + 1)^{\\frac{3}{2}}}{3} + C", explanation: "Combine constants: \\(\\displaystyle\\frac{1}{2}\\cdot\\displaystyle\\frac{2}{3} = \\displaystyle\\frac{1}{3}\\)." }, { stepNumber: 8, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{(x^2+1)^{3/2}}{3}\\right] = \\displaystyle\\frac{1}{3}\\cdot\\displaystyle\\frac{3}{2}(x^2+1)^{1/2}\\cdot 2x = x\\sqrt{x^2+1}\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{(x^2 + 1)^{\\frac{3}{2}}}{3} + C\\)." } },
  { id: "y2in4-015", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 15", difficulty: "Standard", questionText: "Find \\[ \\int \\displaystyle\\frac{x}{\\sqrt{x^2 + 4}}\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["reverse chain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int f'(x)\\bigl[f(x)\\bigr]^n\\,dx = \\displaystyle\\frac{\\bigl[f(x)\\bigr]^{n+1}}{n+1} + C", explanation: "Reverse-chain power rule. Works for negative fractional indices too — including \\(n = -\\displaystyle\\frac{1}{2}\\) (\\(1/\\sqrt{\\;\\cdot\\;}\\))." }, { stepNumber: 2, description: "Rewrite the integrand as a power.", workingLatex: "\\displaystyle\\frac{x}{\\sqrt{x^2 + 4}} = x(x^2 + 4)^{-\\frac{1}{2}}", explanation: "Surfaces the \\(f'\\cdot f^n\\) structure with \\(n = -\\displaystyle\\frac{1}{2}\\)." }, { stepNumber: 3, description: "Identify \\(f\\) and differentiate it.", workingLatex: "f(x) = x^2 + 4 \\;\\Rightarrow\\; f'(x) = 2x", explanation: "Base of the power; the constant \\(4\\) drops out under differentiation." }, { stepNumber: 4, description: "Compare the co-factor to \\(f'(x)\\).", workingLatex: "\\text{Co-factor } x = \\displaystyle\\frac{1}{2}\\,f'(x)", explanation: "Short by a factor of \\(2\\)." }, { stepNumber: 5, description: "Pull out the \\(\\displaystyle\\frac{1}{2}\\).", workingLatex: "\\displaystyle\\int x(x^2 + 4)^{-\\frac{1}{2}}\\,dx = \\displaystyle\\frac{1}{2}\\displaystyle\\int 2x(x^2 + 4)^{-\\frac{1}{2}}\\,dx", explanation: "Brings the co-factor up to exactly \\(f'(x)\\)." }, { stepNumber: 6, description: "Apply the rule with \\(n = -\\displaystyle\\frac{1}{2}\\).", workingLatex: "= \\displaystyle\\frac{1}{2}\\cdot\\displaystyle\\frac{(x^2 + 4)^{\\frac{1}{2}}}{1/2} + C", explanation: "New index is \\(-\\displaystyle\\frac{1}{2} + 1 = \\displaystyle\\frac{1}{2}\\); divide by \\(\\displaystyle\\frac{1}{2}\\), i.e. multiply by \\(2\\)." }, { stepNumber: 7, description: "Tidy.", workingLatex: "= (x^2 + 4)^{\\frac{1}{2}} + C = \\sqrt{x^2 + 4} + C", explanation: "The \\(\\displaystyle\\frac{1}{2}\\) outside cancels with the factor of \\(2\\) from the rule." }, { stepNumber: 8, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\sqrt{x^2 + 4} = \\displaystyle\\frac{2x}{2\\sqrt{x^2 + 4}} = \\displaystyle\\frac{x}{\\sqrt{x^2 + 4}}\\;\\checkmark", explanation: "Confirms the antiderivative." } ], finalAnswer: "\\(\\sqrt{x^2 + 4} + C\\)." } },
  { id: "y2in4-016", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 16", difficulty: "Standard", questionText: "Find \\[ \\int \\sin x\\cos^3 x\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["reverse chain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int f'(x)\\bigl[f(x)\\bigr]^n\\,dx = \\displaystyle\\frac{\\bigl[f(x)\\bigr]^{n+1}}{n+1} + C", explanation: "Reverse-chain power rule." }, { stepNumber: 2, description: "Choose the inner function.", workingLatex: "f(x) = \\cos x", explanation: "Pick \\(\\cos x\\) so that the cubed term becomes \\(f^3\\). Then we check whether the remaining \\(\\sin x\\) factor is (a multiple of) its derivative." }, { stepNumber: 3, description: "Differentiate \\(f\\).", workingLatex: "f'(x) = -\\sin x", explanation: "Standard derivative — minus sign is intrinsic to \\(\\cos\\)'s derivative." }, { stepNumber: 4, description: "Compare the co-factor to \\(f'(x)\\).", workingLatex: "\\text{Co-factor } \\sin x = -f'(x)", explanation: "We have \\(\\sin x\\) but the rule wants \\(-\\sin x\\); the discrepancy is a single minus sign that we will absorb outside the integral." }, { stepNumber: 5, description: "Rewrite with the sign exposed.", workingLatex: "\\displaystyle\\int \\sin x\\cos^3 x\\,dx = -\\displaystyle\\int (-\\sin x)\\cos^3 x\\,dx", explanation: "Inserting two minus signs (one inside, one out) turns the integrand into \\(f'(x)\\bigl[f(x)\\bigr]^3\\) with a clean leading minus." }, { stepNumber: 6, description: "Apply the rule with \\(n = 3\\).", workingLatex: "= -\\displaystyle\\frac{\\cos^4 x}{4} + C", explanation: "Raise the index by one to \\(4\\); divide by \\(4\\); the outer minus stays." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[-\\displaystyle\\frac{\\cos^4 x}{4}\\right] = -\\displaystyle\\frac{4\\cos^3 x\\cdot(-\\sin x)}{4} = \\sin x\\cos^3 x\\;\\checkmark", explanation: "Two minus signs combine to a plus; recovers the integrand." } ], finalAnswer: "\\(-\\displaystyle\\frac{\\cos^4 x}{4} + C\\)." } },
  { id: "y2in4-017", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 17", difficulty: "Standard", questionText: "Find \\[ \\int \\cos x\\sin^4 x\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["reverse chain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int f'(x)\\bigl[f(x)\\bigr]^n\\,dx = \\displaystyle\\frac{\\bigl[f(x)\\bigr]^{n+1}}{n+1} + C", explanation: "Reverse-chain power rule." }, { stepNumber: 2, description: "Choose the inner function.", workingLatex: "f(x) = \\sin x", explanation: "Pick \\(\\sin x\\) so that \\(\\sin^4 x = f^4\\). Then check the remaining \\(\\cos x\\) factor against \\(f'\\)." }, { stepNumber: 3, description: "Differentiate \\(f\\).", workingLatex: "f'(x) = \\cos x", explanation: "Standard derivative." }, { stepNumber: 4, description: "Compare the co-factor to \\(f'(x)\\).", workingLatex: "\\text{Co-factor } \\cos x = f'(x)", explanation: "Exact match — clean \\(f'\\cdot f^n\\) set-up with no constant adjustment." }, { stepNumber: 5, description: "Apply the rule with \\(n = 4\\).", workingLatex: "\\displaystyle\\int \\cos x\\sin^4 x\\,dx = \\displaystyle\\frac{\\sin^5 x}{5} + C", explanation: "Index goes up by one to \\(5\\); divide by \\(5\\)." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{\\sin^5 x}{5}\\right] = \\sin^4 x\\cdot\\cos x\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{\\sin^5 x}{5} + C\\)." } },
  { id: "y2in4-018", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 18", difficulty: "Standard", questionText: "Find \\[ \\int \\sec^2 x\\tan^2 x\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["reverse chain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int f'(x)\\bigl[f(x)\\bigr]^n\\,dx = \\displaystyle\\frac{\\bigl[f(x)\\bigr]^{n+1}}{n+1} + C", explanation: "Reverse-chain power rule." }, { stepNumber: 2, description: "Choose the inner function.", workingLatex: "f(x) = \\tan x", explanation: "Pick \\(\\tan x\\) so that \\(\\tan^2 x = f^2\\). The remaining \\(\\sec^2 x\\) factor should then be \\(f'\\)." }, { stepNumber: 3, description: "Differentiate \\(f\\).", workingLatex: "f'(x) = \\sec^2 x", explanation: "Standard derivative of tangent." }, { stepNumber: 4, description: "Compare the co-factor to \\(f'(x)\\).", workingLatex: "\\text{Co-factor } \\sec^2 x = f'(x)", explanation: "Exact match — clean set-up." }, { stepNumber: 5, description: "Apply the rule with \\(n = 2\\).", workingLatex: "\\displaystyle\\int \\sec^2 x\\tan^2 x\\,dx = \\displaystyle\\frac{\\tan^3 x}{3} + C", explanation: "Index goes to \\(3\\); divide by \\(3\\)." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{\\tan^3 x}{3}\\right] = \\tan^2 x\\cdot\\sec^2 x\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{\\tan^3 x}{3} + C\\)." } },
  { id: "y2in4-019", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 19", difficulty: "Standard", questionText: "Find \\[ \\int e^x(e^x + 1)^3\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["reverse chain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int f'(x)\\bigl[f(x)\\bigr]^n\\,dx = \\displaystyle\\frac{\\bigl[f(x)\\bigr]^{n+1}}{n+1} + C", explanation: "Reverse-chain power rule." }, { stepNumber: 2, description: "Choose the inner function.", workingLatex: "f(x) = e^x + 1", explanation: "Pick the base of the cube as \\(f\\); then test whether \\(f'\\) is the co-factor outside." }, { stepNumber: 3, description: "Differentiate \\(f\\).", workingLatex: "f'(x) = e^x", explanation: "\\(\\displaystyle\\frac{d}{dx}e^x = e^x\\); the \\(+1\\) drops out." }, { stepNumber: 4, description: "Compare the co-factor to \\(f'(x)\\).", workingLatex: "\\text{Co-factor } e^x = f'(x)", explanation: "Exact match — no rescaling needed." }, { stepNumber: 5, description: "Apply the rule with \\(n = 3\\).", workingLatex: "\\displaystyle\\int e^x(e^x + 1)^3\\,dx = \\displaystyle\\frac{(e^x + 1)^4}{4} + C", explanation: "Index to \\(4\\); divide by \\(4\\)." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{(e^x+1)^4}{4}\\right] = (e^x+1)^3\\cdot e^x\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{(e^x + 1)^4}{4} + C\\)." } },
  { id: "y2in4-020", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 20", difficulty: "Standard", questionText: "Find \\[ \\int \\displaystyle\\frac{\\ln x}{x}\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["reverse chain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int f'(x)\\bigl[f(x)\\bigr]^n\\,dx = \\displaystyle\\frac{\\bigl[f(x)\\bigr]^{n+1}}{n+1} + C", explanation: "Reverse-chain power rule. Note the integrand here is NOT \\(f'/f\\) (which would give \\(\\ln\\)); it is \\(f\\cdot f'\\), a power of \\(f\\) with \\(n = 1\\)." }, { stepNumber: 2, description: "Choose the inner function.", workingLatex: "f(x) = \\ln x", explanation: "Pick \\(\\ln x\\) as \\(f\\); then \\(\\displaystyle\\frac{1}{x}\\) (sitting in the denominator) should be \\(f'\\)." }, { stepNumber: 3, description: "Differentiate \\(f\\).", workingLatex: "f'(x) = \\displaystyle\\frac{1}{x}", explanation: "Standard derivative of natural log." }, { stepNumber: 4, description: "Compare the co-factor to \\(f'(x)\\).", workingLatex: "\\text{Co-factor } \\displaystyle\\frac{1}{x} = f'(x)", explanation: "Exact match. The integrand is \\(\\ln x\\cdot\\displaystyle\\frac{1}{x} = f(x)\\cdot f'(x)\\) — power-of-\\(f\\) form with \\(n = 1\\)." }, { stepNumber: 5, description: "Apply the rule with \\(n = 1\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{\\ln x}{x}\\,dx = \\displaystyle\\frac{(\\ln x)^2}{2} + C", explanation: "Index to \\(2\\); divide by \\(2\\)." }, { stepNumber: 6, description: "Common-pitfall note.", workingLatex: "\\text{Don't write } \\ln(\\ln x): \\text{ that would be } \\displaystyle\\int \\displaystyle\\frac{1}{x\\ln x}\\,dx, \\text{ a different problem.}", explanation: "Easy slip — the \\(\\ln/x\\) form looks superficially like \\(f'/f\\) with \\(f = \\ln x\\), but the numerator here is \\(\\ln x\\), not \\(\\displaystyle\\frac{1}{x}\\). The integrand is \\(f\\cdot f'\\), not \\(f'/f\\)." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{(\\ln x)^2}{2}\\right] = \\displaystyle\\frac{2\\ln x\\cdot(1/x)}{2} = \\displaystyle\\frac{\\ln x}{x}\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{(\\ln x)^2}{2} + C\\)." } },
  { id: "y2in4-021", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 21", difficulty: "Standard", questionText: "Find \\[ \\int \\displaystyle\\frac{\\left(\\ln x\\right)^3}{x}\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["reverse chain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int f'(x)\\bigl[f(x)\\bigr]^n\\,dx = \\displaystyle\\frac{\\bigl[f(x)\\bigr]^{n+1}}{n+1} + C", explanation: "Reverse-chain power rule." }, { stepNumber: 2, description: "Choose the inner function.", workingLatex: "f(x) = \\ln x", explanation: "Pick \\(\\ln x\\) so that \\((\\ln x)^3 = f^3\\); the \\(\\displaystyle\\frac{1}{x}\\) in the denominator should be \\(f'\\)." }, { stepNumber: 3, description: "Differentiate \\(f\\).", workingLatex: "f'(x) = \\displaystyle\\frac{1}{x}", explanation: "Standard derivative of \\(\\ln x\\)." }, { stepNumber: 4, description: "Compare the co-factor to \\(f'(x)\\).", workingLatex: "\\text{Co-factor } \\displaystyle\\frac{1}{x} = f'(x)", explanation: "Exact match — clean \\(f'\\cdot f^n\\) form with \\(n = 3\\)." }, { stepNumber: 5, description: "Apply the rule with \\(n = 3\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{(\\ln x)^3}{x}\\,dx = \\displaystyle\\frac{(\\ln x)^4}{4} + C", explanation: "Index to \\(4\\); divide by \\(4\\)." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{(\\ln x)^4}{4}\\right] = (\\ln x)^3\\cdot\\displaystyle\\frac{1}{x}\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{(\\ln x)^4}{4} + C\\)." } },
  { id: "y2in4-022", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 22", difficulty: "Standard", questionText: "Find \\[ \\int xe^{x^2}\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["reverse chain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int g'(x)\\,e^{g(x)}\\,dx = e^{g(x)} + C", explanation: "Reverse-chain rule applied to the exponential. If the inner function's derivative sits outside the exponential as a co-factor, the antiderivative is just \\(e^{g(x)}\\). It reverses \\(\\displaystyle\\frac{d}{dx}e^{g(x)} = e^{g(x)}\\cdot g'(x)\\)." }, { stepNumber: 2, description: "Identify the inner function \\(g\\).", workingLatex: "g(x) = x^2", explanation: "The exponent inside \\(e^{(\\cdot)}\\) — that is what the chain rule was applied to when differentiating, so it is the natural \\(g\\)." }, { stepNumber: 3, description: "Differentiate \\(g\\).", workingLatex: "g'(x) = 2x", explanation: "Power rule." }, { stepNumber: 4, description: "Compare the co-factor to \\(g'(x)\\).", workingLatex: "\\text{Co-factor } x = \\displaystyle\\frac{1}{2}\\,g'(x)", explanation: "Short by a factor of \\(2\\)." }, { stepNumber: 5, description: "Pull out the \\(\\displaystyle\\frac{1}{2}\\).", workingLatex: "\\displaystyle\\int xe^{x^2}\\,dx = \\displaystyle\\frac{1}{2}\\displaystyle\\int 2x\\,e^{x^2}\\,dx", explanation: "Brings the co-factor up to exactly \\(g'(x)\\)." }, { stepNumber: 6, description: "Apply the rule.", workingLatex: "= \\displaystyle\\frac{1}{2}e^{x^2} + C", explanation: "The bracketed integral is now exactly the rule's template." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{e^{x^2}}{2}\\right] = \\displaystyle\\frac{e^{x^2}\\cdot 2x}{2} = xe^{x^2}\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{e^{x^2}}{2} + C\\)." } },
  { id: "y2in4-023", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 23", difficulty: "Standard", questionText: "Find \\[ \\int x^2 e^{x^3}\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["reverse chain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int g'(x)\\,e^{g(x)}\\,dx = e^{g(x)} + C", explanation: "Reverse-chain exponential rule." }, { stepNumber: 2, description: "Identify the inner function \\(g\\).", workingLatex: "g(x) = x^3", explanation: "The exponent inside the exponential." }, { stepNumber: 3, description: "Differentiate \\(g\\).", workingLatex: "g'(x) = 3x^2", explanation: "Power rule." }, { stepNumber: 4, description: "Compare the co-factor to \\(g'(x)\\).", workingLatex: "\\text{Co-factor } x^2 = \\displaystyle\\frac{1}{3}\\,g'(x)", explanation: "Short by a factor of \\(3\\); need \\(\\displaystyle\\frac{1}{3}\\) outside." }, { stepNumber: 5, description: "Pull out the \\(\\displaystyle\\frac{1}{3}\\).", workingLatex: "\\displaystyle\\int x^2 e^{x^3}\\,dx = \\displaystyle\\frac{1}{3}\\displaystyle\\int 3x^2 e^{x^3}\\,dx", explanation: "Brings the co-factor up to exactly \\(g'(x) = 3x^2\\)." }, { stepNumber: 6, description: "Apply the rule.", workingLatex: "= \\displaystyle\\frac{e^{x^3}}{3} + C", explanation: "The bracketed integral is now the rule's template." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{e^{x^3}}{3}\\right] = \\displaystyle\\frac{e^{x^3}\\cdot 3x^2}{3} = x^2 e^{x^3}\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{e^{x^3}}{3} + C\\)." } },
  { id: "y2in4-024", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 24", difficulty: "Standard", questionText: "Find \\[ \\int \\cos x\\,e^{\\sin x}\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["reverse chain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int g'(x)\\,e^{g(x)}\\,dx = e^{g(x)} + C", explanation: "Reverse-chain exponential rule." }, { stepNumber: 2, description: "Identify the inner function \\(g\\).", workingLatex: "g(x) = \\sin x", explanation: "The exponent inside \\(e^{(\\cdot)}\\)." }, { stepNumber: 3, description: "Differentiate \\(g\\).", workingLatex: "g'(x) = \\cos x", explanation: "Standard derivative." }, { stepNumber: 4, description: "Compare the co-factor to \\(g'(x)\\).", workingLatex: "\\text{Co-factor } \\cos x = g'(x)", explanation: "Exact match — no rescaling required." }, { stepNumber: 5, description: "Apply the rule.", workingLatex: "\\displaystyle\\int \\cos x\\,e^{\\sin x}\\,dx = e^{\\sin x} + C", explanation: "Direct rule application." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[e^{\\sin x}\\right] = e^{\\sin x}\\cdot\\cos x\\;\\checkmark", explanation: "Chain rule on the outer exp times the inner \\(\\sin\\) derivative; recovers the integrand." } ], finalAnswer: "\\(e^{\\sin x} + C\\)." } },
  { id: "y2in4-025", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 25", difficulty: "Standard", questionText: "Find \\[ \\int \\sec^2 x\\,e^{\\tan x}\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["reverse chain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int g'(x)\\,e^{g(x)}\\,dx = e^{g(x)} + C", explanation: "Reverse-chain exponential rule." }, { stepNumber: 2, description: "Identify the inner function \\(g\\).", workingLatex: "g(x) = \\tan x", explanation: "The exponent inside the exponential." }, { stepNumber: 3, description: "Differentiate \\(g\\).", workingLatex: "g'(x) = \\sec^2 x", explanation: "Standard derivative of \\(\\tan\\)." }, { stepNumber: 4, description: "Compare the co-factor to \\(g'(x)\\).", workingLatex: "\\text{Co-factor } \\sec^2 x = g'(x)", explanation: "Exact match — no rescaling." }, { stepNumber: 5, description: "Apply the rule.", workingLatex: "\\displaystyle\\int \\sec^2 x\\,e^{\\tan x}\\,dx = e^{\\tan x} + C", explanation: "Direct rule application." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[e^{\\tan x}\\right] = e^{\\tan x}\\cdot\\sec^2 x\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(e^{\\tan x} + C\\)." } },
  // ── Mixed reverse chain ────
  { id: "y2in4-026", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 26", difficulty: "Standard", questionText: "Find \\[ \\int \\displaystyle\\frac{\\sec^2 x}{\\tan x}\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{f'(x)}{f(x)}\\,dx = \\ln|f(x)| + C", explanation: "Reverse-chain log pattern." }, { stepNumber: 2, description: "Identify \\(f\\).", workingLatex: "f(x) = \\tan x", explanation: "Denominator as \\(f\\); test whether its derivative is the numerator." }, { stepNumber: 3, description: "Differentiate \\(f\\).", workingLatex: "f'(x) = \\sec^2 x", explanation: "Standard derivative of tangent." }, { stepNumber: 4, description: "Compare numerator to \\(f'(x)\\).", workingLatex: "\\text{Numerator } \\sec^2 x = f'(x)", explanation: "Exact match — clean \\(f'/f\\) form." }, { stepNumber: 5, description: "Apply the rule.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{\\sec^2 x}{\\tan x}\\,dx = \\ln|\\tan x| + C", explanation: "Modulus bars stay — \\(\\tan x\\) changes sign at every \\(x = \\displaystyle\\frac{\\pi}{2} + k\\pi\\)." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\ln|\\tan x| = \\displaystyle\\frac{\\sec^2 x}{\\tan x}\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\ln|\\tan x| + C\\)." } },
  { id: "y2in4-027", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 27", difficulty: "Standard", questionText: "Find \\[ \\int \\displaystyle\\frac{\\sin x}{1 + \\cos x}\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{f'(x)}{f(x)}\\,dx = \\ln|f(x)| + C", explanation: "Reverse-chain log pattern." }, { stepNumber: 2, description: "Identify \\(f\\).", workingLatex: "f(x) = 1 + \\cos x", explanation: "Denominator as \\(f\\)." }, { stepNumber: 3, description: "Differentiate \\(f\\).", workingLatex: "f'(x) = -\\sin x", explanation: "The \\(1\\) drops out; \\(\\displaystyle\\frac{d}{dx}\\cos x = -\\sin x\\)." }, { stepNumber: 4, description: "Compare numerator to \\(f'(x)\\).", workingLatex: "\\text{Numerator } \\sin x = -f'(x)", explanation: "We have \\(\\sin x\\) but need \\(-\\sin x\\); off by a single minus sign that we will absorb outside." }, { stepNumber: 5, description: "Rewrite the integral with the matching numerator.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{\\sin x}{1 + \\cos x}\\,dx = -\\displaystyle\\int \\displaystyle\\frac{-\\sin x}{1 + \\cos x}\\,dx", explanation: "Two minus signs (inside and outside) leave the value unchanged but put the integrand into clean \\(f'/f\\) form." }, { stepNumber: 6, description: "Apply the rule.", workingLatex: "= -\\ln|1 + \\cos x| + C", explanation: "The bracketed integral gives \\(\\ln|f|\\); the outer minus stays." }, { stepNumber: 7, description: "Note on modulus bars.", workingLatex: "1 + \\cos x \\ge 0 \\text{ always (zero when } x = (2k+1)\\pi\\text{).}", explanation: "Since the argument is non-negative, the bars are optional; the antiderivative is defined wherever \\(\\cos x \\neq -1\\)." }, { stepNumber: 8, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[-\\ln|1+\\cos x|\\right] = -\\displaystyle\\frac{-\\sin x}{1+\\cos x} = \\displaystyle\\frac{\\sin x}{1+\\cos x}\\;\\checkmark", explanation: "Two minuses combine to a plus — recovers the integrand." } ], finalAnswer: "\\(-\\ln|1 + \\cos x| + C\\)." } },
  { id: "y2in4-028", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 28", difficulty: "Standard", questionText: "Find \\[ \\int \\displaystyle\\frac{\\cos x}{1 + \\sin x}\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{f'(x)}{f(x)}\\,dx = \\ln|f(x)| + C", explanation: "Reverse-chain log pattern." }, { stepNumber: 2, description: "Identify \\(f\\).", workingLatex: "f(x) = 1 + \\sin x", explanation: "Denominator as \\(f\\)." }, { stepNumber: 3, description: "Differentiate \\(f\\).", workingLatex: "f'(x) = \\cos x", explanation: "The \\(1\\) drops out; \\(\\displaystyle\\frac{d}{dx}\\sin x = \\cos x\\)." }, { stepNumber: 4, description: "Compare numerator to \\(f'(x)\\).", workingLatex: "\\text{Numerator } \\cos x = f'(x)", explanation: "Exact match — clean \\(f'/f\\) form." }, { stepNumber: 5, description: "Apply the rule.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{\\cos x}{1 + \\sin x}\\,dx = \\ln|1 + \\sin x| + C", explanation: "Direct application." }, { stepNumber: 6, description: "Drop the modulus bars.", workingLatex: "= \\ln(1 + \\sin x) + C", explanation: "Since \\(-1 \\le \\sin x \\le 1\\), we have \\(1 + \\sin x \\ge 0\\), with equality only at isolated points; the bars can be dropped where convenient." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\ln(1 + \\sin x) = \\displaystyle\\frac{\\cos x}{1 + \\sin x}\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\ln(1 + \\sin x) + C\\)." } },
  { id: "y2in4-029", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 29", difficulty: "Standard", questionText: "Find \\[ \\int \\displaystyle\\frac{2x + 4}{x^2 + 4x + 7}\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{f'(x)}{f(x)}\\,dx = \\ln|f(x)| + C", explanation: "Reverse-chain log pattern." }, { stepNumber: 2, description: "Identify \\(f\\).", workingLatex: "f(x) = x^2 + 4x + 7", explanation: "Denominator as \\(f\\)." }, { stepNumber: 3, description: "Differentiate \\(f\\).", workingLatex: "f'(x) = 2x + 4", explanation: "Term-by-term differentiation." }, { stepNumber: 4, description: "Compare numerator to \\(f'(x)\\).", workingLatex: "\\text{Numerator } 2x + 4 = f'(x)", explanation: "Exact match — clean \\(f'/f\\) form." }, { stepNumber: 5, description: "Apply the rule.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{2x + 4}{x^2 + 4x + 7}\\,dx = \\ln|x^2 + 4x + 7| + C", explanation: "Direct rule application." }, { stepNumber: 6, description: "Drop the modulus bars.", workingLatex: "x^2 + 4x + 7 = (x + 2)^2 + 3 \\ge 3 > 0 \\;\\Rightarrow\\; = \\ln(x^2 + 4x + 7) + C", explanation: "Completing the square shows the quadratic is always positive; bars are redundant." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\ln(x^2 + 4x + 7) = \\displaystyle\\frac{2x + 4}{x^2 + 4x + 7}\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\ln(x^2 + 4x + 7) + C\\)." } },
  { id: "y2in4-030", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 30", difficulty: "Standard", questionText: "Find \\[ \\int \\displaystyle\\frac{x^3}{x^4 + 1}\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{f'(x)}{f(x)}\\,dx = \\ln|f(x)| + C", explanation: "Reverse-chain log pattern." }, { stepNumber: 2, description: "Identify \\(f\\).", workingLatex: "f(x) = x^4 + 1", explanation: "Denominator as \\(f\\)." }, { stepNumber: 3, description: "Differentiate \\(f\\).", workingLatex: "f'(x) = 4x^3", explanation: "Power rule." }, { stepNumber: 4, description: "Compare numerator to \\(f'(x)\\).", workingLatex: "\\text{Numerator } x^3 = \\displaystyle\\frac{1}{4}\\,f'(x)", explanation: "Short by a factor of \\(4\\); need \\(\\displaystyle\\frac{1}{4}\\) outside." }, { stepNumber: 5, description: "Pull out the \\(\\displaystyle\\frac{1}{4}\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{x^3}{x^4 + 1}\\,dx = \\displaystyle\\frac{1}{4}\\displaystyle\\int \\displaystyle\\frac{4x^3}{x^4 + 1}\\,dx", explanation: "Brings the numerator up to exactly \\(f'(x)\\)." }, { stepNumber: 6, description: "Apply the rule.", workingLatex: "= \\displaystyle\\frac{1}{4}\\ln|x^4 + 1| + C = \\displaystyle\\frac{1}{4}\\ln(x^4 + 1) + C", explanation: "Since \\(x^4 + 1 \\ge 1 > 0\\), the bars can be dropped." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{1}{4}\\ln(x^4+1)\\right] = \\displaystyle\\frac{1}{4}\\cdot\\displaystyle\\frac{4x^3}{x^4+1} = \\displaystyle\\frac{x^3}{x^4+1}\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{4}\\ln(x^4 + 1) + C\\)." } },
  // ── Tricky: f' on top adjusted by constant ────
  { id: "y2in4-031", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 31", difficulty: "Standard", questionText: "Find \\[ \\int \\displaystyle\\frac{x + 1}{x^2 + 2x + 5}\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{f'(x)}{f(x)}\\,dx = \\ln|f(x)| + C", explanation: "Reverse-chain log pattern." }, { stepNumber: 2, description: "Identify \\(f\\).", workingLatex: "f(x) = x^2 + 2x + 5", explanation: "Denominator as \\(f\\)." }, { stepNumber: 3, description: "Differentiate \\(f\\).", workingLatex: "f'(x) = 2x + 2 = 2(x + 1)", explanation: "Factor out the \\(2\\) — makes the comparison with the numerator transparent." }, { stepNumber: 4, description: "Compare numerator to \\(f'(x)\\).", workingLatex: "\\text{Numerator } x + 1 = \\displaystyle\\frac{1}{2}\\,f'(x)", explanation: "Short by a factor of \\(2\\)." }, { stepNumber: 5, description: "Pull out the \\(\\displaystyle\\frac{1}{2}\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{x + 1}{x^2 + 2x + 5}\\,dx = \\displaystyle\\frac{1}{2}\\displaystyle\\int \\displaystyle\\frac{2(x + 1)}{x^2 + 2x + 5}\\,dx", explanation: "Brings the numerator up to exactly \\(f'(x)\\)." }, { stepNumber: 6, description: "Apply the rule.", workingLatex: "= \\displaystyle\\frac{1}{2}\\ln|x^2 + 2x + 5| + C", explanation: "Direct application." }, { stepNumber: 7, description: "Drop the modulus bars.", workingLatex: "x^2 + 2x + 5 = (x + 1)^2 + 4 \\ge 4 > 0 \\;\\Rightarrow\\; = \\displaystyle\\frac{1}{2}\\ln(x^2 + 2x + 5) + C", explanation: "Completing the square shows the quadratic is always positive." }, { stepNumber: 8, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{1}{2}\\ln(x^2+2x+5)\\right] = \\displaystyle\\frac{1}{2}\\cdot\\displaystyle\\frac{2x+2}{x^2+2x+5} = \\displaystyle\\frac{x+1}{x^2+2x+5}\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{2}\\ln(x^2 + 2x + 5) + C\\)." } },
  { id: "y2in4-032", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 32", difficulty: "Foundation", questionText: "Find \\[ \\int \\displaystyle\\frac{6x}{3x^2 + 5}\\,dx \\]", marks: 2, examStyle: false, yearCreated: 2026, tags: ["log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{f'(x)}{f(x)}\\,dx = \\ln|f(x)| + C", explanation: "Reverse-chain log rule." }, { stepNumber: 2, description: "Identify \\(f\\).", workingLatex: "f(x) = 3x^2 + 5", explanation: "Denominator as \\(f\\)." }, { stepNumber: 3, description: "Differentiate \\(f\\).", workingLatex: "f'(x) = 6x", explanation: "Power rule, with the constant \\(3\\) multiplying through." }, { stepNumber: 4, description: "Compare numerator to \\(f'(x)\\).", workingLatex: "\\text{Numerator } 6x = f'(x)", explanation: "Exact match — clean \\(f'/f\\) form." }, { stepNumber: 5, description: "Apply the rule.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{6x}{3x^2 + 5}\\,dx = \\ln(3x^2 + 5) + C", explanation: "\\(3x^2 + 5 \\ge 5 > 0\\) always, so the bars can be dropped." } ], finalAnswer: "\\(\\ln(3x^2 + 5) + C\\)." } },
  { id: "y2in4-033", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 33", difficulty: "Standard", questionText: "Find \\[ \\int \\displaystyle\\frac{5x^4}{x^5 - 2}\\,dx \\]", marks: 2, examStyle: false, yearCreated: 2026, tags: ["log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{f'(x)}{f(x)}\\,dx = \\ln|f(x)| + C", explanation: "Reverse-chain log pattern." }, { stepNumber: 2, description: "Identify \\(f\\).", workingLatex: "f(x) = x^5 - 2", explanation: "Denominator as \\(f\\)." }, { stepNumber: 3, description: "Differentiate \\(f\\).", workingLatex: "f'(x) = 5x^4", explanation: "Power rule." }, { stepNumber: 4, description: "Compare numerator to \\(f'(x)\\).", workingLatex: "\\text{Numerator } 5x^4 = f'(x)", explanation: "Exact match — clean \\(f'/f\\) form." }, { stepNumber: 5, description: "Apply the rule.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{5x^4}{x^5 - 2}\\,dx = \\ln|x^5 - 2| + C", explanation: "Keep modulus bars: \\(x^5 - 2\\) changes sign at \\(x = 2^{1/5}\\), so the argument can be negative." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\ln|x^5 - 2| = \\displaystyle\\frac{5x^4}{x^5 - 2}\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\ln|x^5 - 2| + C\\)." } },
  { id: "y2in4-034", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 34", difficulty: "Standard", questionText: "Find \\[ \\int \\cot x\\,dx \\]", marks: 2, examStyle: false, yearCreated: 2026, tags: ["log"], workedSolution: { steps: [ { stepNumber: 1, description: "Why we need to rewrite first.", workingLatex: "\\cot x \\text{ is not on the standard antiderivative list.}", explanation: "We must convert it into a quotient where the numerator is the derivative of the denominator — that is what splitting \\(\\cot x = \\cos x/\\sin x\\) achieves." }, { stepNumber: 2, description: "Rewrite \\(\\cot x\\) in \\(f'/f\\) form.", workingLatex: "\\cot x = \\displaystyle\\frac{\\cos x}{\\sin x}", explanation: "Definition of cotangent — now the integrand is a quotient." }, { stepNumber: 3, description: "State the rule used.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{f'(x)}{f(x)}\\,dx = \\ln|f(x)| + C", explanation: "Reverse-chain log pattern." }, { stepNumber: 4, description: "Identify \\(f\\) and differentiate it.", workingLatex: "f(x) = \\sin x \\;\\Rightarrow\\; f'(x) = \\cos x", explanation: "Denominator as \\(f\\); its derivative \\(\\cos x\\) is exactly the numerator." }, { stepNumber: 5, description: "Apply the rule.", workingLatex: "\\displaystyle\\int \\cot x\\,dx = \\ln|\\sin x| + C", explanation: "Modulus bars are required — \\(\\sin x\\) is negative on \\((\\pi, 2\\pi)\\) and elsewhere." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\ln|\\sin x| = \\displaystyle\\frac{\\cos x}{\\sin x} = \\cot x\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\ln|\\sin x| + C\\)." } },
  { id: "y2in4-035", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 35", difficulty: "Challenge", questionText: "Find \\[ \\int \\displaystyle\\frac{1}{x\\ln(3x)}\\,dx \\]", marks: 4, examStyle: true, yearCreated: 2026, tags: ["log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int F(g(x))g'(x)\\,dx = \\displaystyle\\int F(u)\\,du", explanation: "Standard \\(u\\)-substitution template. We will use it because the integrand has a nested log and (almost) its derivative." }, { stepNumber: 2, description: "Why u-sub here.", workingLatex: "\\text{Spot: } \\ln(3x) \\text{ in the denominator and } \\displaystyle\\frac{1}{x}\\,dx \\text{ as a co-factor.}", explanation: "The composite \\(\\ln(3x)\\) appears, and its derivative — modulo a constant — sits in the integrand. Substitution will collapse the nesting." }, { stepNumber: 3, description: "Choose \\(u\\).", workingLatex: "u = \\ln(3x)", explanation: "Take \\(u\\) to be the innermost composite — the inside of the outer log." }, { stepNumber: 4, description: "Compute \\(du\\).", workingLatex: "du = \\displaystyle\\frac{1}{3x}\\cdot 3\\,dx = \\displaystyle\\frac{1}{x}\\,dx", explanation: "Chain rule: derivative of \\(\\ln(3x)\\) is \\(\\displaystyle\\frac{1}{3x}\\) times the derivative of the inside, which is \\(3\\); the \\(3\\)s cancel. A common slip is to forget the inner derivative entirely." }, { stepNumber: 5, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{1}{x\\ln(3x)}\\,dx = \\displaystyle\\int \\displaystyle\\frac{1}{\\ln(3x)}\\cdot\\displaystyle\\frac{1}{x}\\,dx = \\displaystyle\\int \\displaystyle\\frac{1}{u}\\,du", explanation: "Replace \\(\\ln(3x) \\to u\\) and \\(\\displaystyle\\frac{1}{x}\\,dx \\to du\\); the whole expression becomes the standard \\(1/u\\) integral." }, { stepNumber: 6, description: "Integrate in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{1}{u}\\,du = \\ln|u| + C", explanation: "Standard antiderivative." }, { stepNumber: 7, description: "Back-substitute.", workingLatex: "= \\ln|\\ln(3x)| + C", explanation: "Replace \\(u\\) with its definition. Modulus bars matter — \\(\\ln(3x) < 0\\) for \\(0 < x < 1/3\\)." }, { stepNumber: 8, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\ln|\\ln(3x)| = \\displaystyle\\frac{1}{\\ln(3x)}\\cdot\\displaystyle\\frac{1}{x} = \\displaystyle\\frac{1}{x\\ln(3x)}\\;\\checkmark", explanation: "Two nested chain-rule applications recover the integrand." } ], finalAnswer: "\\(\\ln|\\ln(3x)| + C\\)." } },
  // ── Definite ────
  { id: "y2in4-036", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 36", difficulty: "Standard", questionText: "Evaluate \\[ \\int_0^2 \\displaystyle\\frac{x}{x^2 + 1}\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["definite"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{f'(x)}{f(x)}\\,dx = \\ln|f(x)| + C", explanation: "Reverse-chain log pattern; the fundamental theorem then turns the antiderivative into a number once the limits are applied." }, { stepNumber: 2, description: "Identify \\(f\\) and differentiate it.", workingLatex: "f(x) = x^2 + 1 \\;\\Rightarrow\\; f'(x) = 2x", explanation: "Denominator as \\(f\\); its derivative is \\(2x\\)." }, { stepNumber: 3, description: "Compare numerator to \\(f'(x)\\).", workingLatex: "\\text{Numerator } x = \\displaystyle\\frac{1}{2}\\,f'(x)", explanation: "Short by a factor of \\(2\\); compensate with \\(\\displaystyle\\frac{1}{2}\\)." }, { stepNumber: 4, description: "Find the antiderivative.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{x}{x^2 + 1}\\,dx = \\displaystyle\\frac{1}{2}\\ln(x^2 + 1) + C", explanation: "Pull out the \\(\\displaystyle\\frac{1}{2}\\), apply \\(f'/f\\) rule; \\(x^2 + 1 > 0\\) so bars drop." }, { stepNumber: 5, description: "Apply the limits.", workingLatex: "\\left[\\displaystyle\\frac{1}{2}\\ln(x^2 + 1)\\right]_0^2 = \\displaystyle\\frac{1}{2}\\ln 5 - \\displaystyle\\frac{1}{2}\\ln 1", explanation: "Upper minus lower, by the fundamental theorem." }, { stepNumber: 6, description: "Simplify.", workingLatex: "= \\displaystyle\\frac{1}{2}\\ln 5 - 0 = \\displaystyle\\frac{1}{2}\\ln 5", explanation: "\\(\\ln 1 = 0\\); the answer is positive since \\(\\ln 5 > 0\\)." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{2}\\ln 5\\)." } },
  { id: "y2in4-037", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 37", difficulty: "Standard", questionText: "Evaluate \\[ \\int_0^{\\pi/4} \\tan x\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["definite"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the antiderivative of \\(\\tan x\\).", workingLatex: "\\displaystyle\\int \\tan x\\,dx = -\\ln|\\cos x| + C", explanation: "From the \\(f'/f\\) rule with \\(f = \\cos x\\); the integrand is \\(\\sin x/\\cos x = -(-\\sin x)/\\cos x = -f'/f\\)." }, { stepNumber: 2, description: "Apply the limits.", workingLatex: "\\Bigl[-\\ln|\\cos x|\\Bigr]_0^{\\pi/4} = -\\ln\\!\\left|\\cos\\displaystyle\\frac{\\pi}{4}\\right| - \\left(-\\ln|\\cos 0|\\right)", explanation: "Upper minus lower; the double-minus at the lower limit will flip to a plus." }, { stepNumber: 3, description: "Plug in numerical values of cosine.", workingLatex: "\\cos\\displaystyle\\frac{\\pi}{4} = \\displaystyle\\frac{1}{\\sqrt 2}, \\quad \\cos 0 = 1", explanation: "Standard exact values." }, { stepNumber: 4, description: "Substitute.", workingLatex: "= -\\ln\\displaystyle\\frac{1}{\\sqrt 2} + \\ln 1 = -\\ln\\displaystyle\\frac{1}{\\sqrt 2}", explanation: "\\(\\ln 1 = 0\\), so the second term vanishes." }, { stepNumber: 5, description: "Simplify using log laws.", workingLatex: "-\\ln\\displaystyle\\frac{1}{\\sqrt 2} = \\ln\\sqrt 2", explanation: "Using \\(-\\ln(1/a) = \\ln a\\)." }, { stepNumber: 6, description: "Tidy.", workingLatex: "\\ln\\sqrt 2 = \\displaystyle\\frac{1}{2}\\ln 2", explanation: "Using \\(\\ln(a^{1/2}) = \\displaystyle\\frac{1}{2}\\ln a\\). Positive answer makes sense: \\(\\tan x > 0\\) on \\((0, \\pi/4)\\)." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{2}\\ln 2\\)." } },
  { id: "y2in4-038", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 38", difficulty: "Standard", questionText: "Evaluate \\[ \\int_0^1 \\displaystyle\\frac{x}{\\sqrt{x^2 + 1}}\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["definite"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int f'(x)\\bigl[f(x)\\bigr]^n\\,dx = \\displaystyle\\frac{\\bigl[f(x)\\bigr]^{n+1}}{n+1} + C", explanation: "Reverse-chain power rule." }, { stepNumber: 2, description: "Identify \\(f\\) and differentiate it.", workingLatex: "f(x) = x^2 + 1, \\; f'(x) = 2x, \\; n = -\\displaystyle\\frac{1}{2}", explanation: "Surd as a power: \\(1/\\sqrt{\\cdot} = (\\cdot)^{-1/2}\\)." }, { stepNumber: 3, description: "Compare the co-factor to \\(f'(x)\\) and rescale.", workingLatex: "\\text{Co-factor } x = \\displaystyle\\frac{1}{2}f'(x)", explanation: "Short by a factor of \\(2\\)." }, { stepNumber: 4, description: "Find the antiderivative.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{x}{\\sqrt{x^2 + 1}}\\,dx = \\displaystyle\\frac{1}{2}\\cdot\\displaystyle\\frac{(x^2 + 1)^{1/2}}{1/2} + C = \\sqrt{x^2 + 1} + C", explanation: "The \\(\\displaystyle\\frac{1}{2}\\) outside cancels with division by \\(\\displaystyle\\frac{1}{2}\\) inside." }, { stepNumber: 5, description: "Apply the limits.", workingLatex: "\\Bigl[\\sqrt{x^2 + 1}\\Bigr]_0^1 = \\sqrt 2 - \\sqrt 1", explanation: "Upper minus lower." }, { stepNumber: 6, description: "Simplify.", workingLatex: "= \\sqrt 2 - 1", explanation: "Positive, as expected since the integrand is non-negative on \\([0,1]\\)." } ], finalAnswer: "\\(\\sqrt 2 - 1\\)." } },
  { id: "y2in4-039", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 39", difficulty: "Foundation", questionText: "Evaluate \\[ \\int_0^{\\pi/2} \\sin x\\cos x\\,dx \\]", marks: 2, examStyle: false, yearCreated: 2026, tags: ["definite"], workedSolution: { steps: [ { stepNumber: 1, description: "Find the antiderivative.", workingLatex: "\\displaystyle\\int \\sin x\\cos x\\,dx = \\displaystyle\\frac{\\sin^2 x}{2} + C", explanation: "Reverse-chain power rule with \\(f = \\sin x\\), \\(f' = \\cos x\\), \\(n = 1\\); the integrand is \\(f\\cdot f'\\)." }, { stepNumber: 2, description: "Apply the limits.", workingLatex: "\\left[\\displaystyle\\frac{\\sin^2 x}{2}\\right]_0^{\\pi/2} = \\displaystyle\\frac{\\sin^2(\\pi/2)}{2} - \\displaystyle\\frac{\\sin^2 0}{2}", explanation: "Upper minus lower." }, { stepNumber: 3, description: "Plug in values.", workingLatex: "\\sin\\displaystyle\\frac{\\pi}{2} = 1, \\;\\; \\sin 0 = 0", explanation: "Standard exact values." }, { stepNumber: 4, description: "Simplify.", workingLatex: "= \\displaystyle\\frac{1}{2} - 0 = \\displaystyle\\frac{1}{2}", explanation: "Positive, as expected since the integrand is non-negative on \\([0, \\pi/2]\\)." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{2}\\)." } },
  { id: "y2in4-040", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 40", difficulty: "Standard", questionText: "Evaluate \\[ \\int_1^e \\displaystyle\\frac{\\ln x}{x}\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["definite"], workedSolution: { steps: [ { stepNumber: 1, description: "Find the antiderivative.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{\\ln x}{x}\\,dx = \\displaystyle\\frac{(\\ln x)^2}{2} + C", explanation: "Reverse-chain power rule with \\(f = \\ln x\\), \\(f' = 1/x\\), \\(n = 1\\); the integrand is \\(f\\cdot f'\\)." }, { stepNumber: 2, description: "Apply the limits.", workingLatex: "\\left[\\displaystyle\\frac{(\\ln x)^2}{2}\\right]_1^e = \\displaystyle\\frac{(\\ln e)^2}{2} - \\displaystyle\\frac{(\\ln 1)^2}{2}", explanation: "Upper minus lower." }, { stepNumber: 3, description: "Plug in values.", workingLatex: "\\ln e = 1, \\;\\; \\ln 1 = 0", explanation: "Definitions of natural log." }, { stepNumber: 4, description: "Simplify.", workingLatex: "= \\displaystyle\\frac{1}{2} - 0 = \\displaystyle\\frac{1}{2}", explanation: "Positive, as expected since the integrand is non-negative on \\([1, e]\\)." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{2}\\)." } },
  { id: "y2in4-041", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 41", difficulty: "Standard", questionText: "Evaluate \\[ \\int_0^1 xe^{x^2}\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["definite"], workedSolution: { steps: [ { stepNumber: 1, description: "Find the antiderivative.", workingLatex: "\\displaystyle\\int xe^{x^2}\\,dx = \\displaystyle\\frac{e^{x^2}}{2} + C", explanation: "Reverse-chain exponential rule with \\(g = x^2\\), \\(g' = 2x\\); compensate with \\(\\displaystyle\\frac{1}{2}\\)." }, { stepNumber: 2, description: "Apply the limits.", workingLatex: "\\left[\\displaystyle\\frac{e^{x^2}}{2}\\right]_0^1 = \\displaystyle\\frac{e^1}{2} - \\displaystyle\\frac{e^0}{2}", explanation: "Upper minus lower." }, { stepNumber: 3, description: "Plug in values.", workingLatex: "e^1 = e, \\;\\; e^0 = 1", explanation: "Standard exponential values." }, { stepNumber: 4, description: "Simplify.", workingLatex: "= \\displaystyle\\frac{e}{2} - \\displaystyle\\frac{1}{2} = \\displaystyle\\frac{e - 1}{2}", explanation: "Positive, as expected since the integrand is non-negative on \\([0,1]\\)." } ], finalAnswer: "\\(\\displaystyle\\frac{e - 1}{2}\\)." } },
  { id: "y2in4-042", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 42", difficulty: "Challenge", questionText: "Evaluate \\[ \\int_1^{e^2} \\displaystyle\\frac{1}{x\\ln x}\\,dx \\] (explain limits).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["definite"], workedSolution: { steps: [ { stepNumber: 1, description: "Find the antiderivative.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{1}{x\\ln x}\\,dx = \\ln|\\ln x| + C", explanation: "Substitution \\(u = \\ln x\\), \\(du = dx/x\\) collapses this to \\(\\int du/u = \\ln|u|\\)." }, { stepNumber: 2, description: "Examine the lower limit.", workingLatex: "\\text{At } x = 1: \\;\\ln x = 0 \\;\\Rightarrow\\; \\ln|\\ln x| = \\ln 0 \\text{ undefined}", explanation: "The integrand \\(1/(x\\ln x)\\) is singular at \\(x = 1\\) because \\(\\ln x \\to 0\\), and the antiderivative blows up there. The integral is therefore improper at the lower limit." }, { stepNumber: 3, description: "Set up the improper integral as a limit.", workingLatex: "\\displaystyle\\int_1^{e^2} \\displaystyle\\frac{1}{x\\ln x}\\,dx = \\lim_{a\\to 1^+}\\Bigl[\\ln|\\ln x|\\Bigr]_a^{e^2}", explanation: "Replace the troublesome lower limit by a parameter \\(a > 1\\), evaluate, then let \\(a \\to 1^+\\)." }, { stepNumber: 4, description: "Evaluate the bracket.", workingLatex: "\\Bigl[\\ln|\\ln x|\\Bigr]_a^{e^2} = \\ln|\\ln e^2| - \\ln|\\ln a| = \\ln 2 - \\ln|\\ln a|", explanation: "Upper minus lower. \\(\\ln e^2 = 2\\), so the upper term is \\(\\ln 2\\)." }, { stepNumber: 5, description: "Analyse the limit.", workingLatex: "\\text{As } a \\to 1^+: \\;\\; \\ln a \\to 0^+ \\;\\Rightarrow\\; \\ln|\\ln a| \\to -\\infty", explanation: "Taking log of a positive quantity tending to zero gives \\(-\\infty\\)." }, { stepNumber: 6, description: "Conclude divergence.", workingLatex: "\\lim_{a\\to 1^+}\\bigl(\\ln 2 - \\ln|\\ln a|\\bigr) = \\ln 2 - (-\\infty) = +\\infty", explanation: "The improper integral diverges to \\(+\\infty\\); it has no finite value." } ], finalAnswer: "Integral diverges (improper)." } },
  // ── More ────
  { id: "y2in4-043", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 43", difficulty: "Foundation", questionText: "Find \\[ \\int \\displaystyle\\frac{2}{x + 1}\\,dx \\]", marks: 2, examStyle: false, yearCreated: 2026, tags: ["log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{f'(x)}{f(x)}\\,dx = \\ln|f(x)| + C", explanation: "Reverse-chain log pattern." }, { stepNumber: 2, description: "Take out the constant 2.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{2}{x + 1}\\,dx = 2\\displaystyle\\int \\displaystyle\\frac{1}{x + 1}\\,dx", explanation: "Linearity lets us pull constants out of integrals." }, { stepNumber: 3, description: "Identify \\(f\\) and differentiate it.", workingLatex: "f(x) = x + 1 \\;\\Rightarrow\\; f'(x) = 1", explanation: "Denominator as \\(f\\); its derivative is \\(1\\), which is exactly what sits on top after the \\(2\\) is pulled out." }, { stepNumber: 4, description: "Apply the rule.", workingLatex: "= 2\\ln|x + 1| + C", explanation: "Modulus bars stay — \\(x + 1\\) changes sign at \\(x = -1\\)." } ], finalAnswer: "\\(2\\ln|x + 1| + C\\)." } },
  { id: "y2in4-044", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 44", difficulty: "Standard", questionText: "Find \\[ \\int \\displaystyle\\frac{x^2 + 1}{x^3 + 3x}\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{f'(x)}{f(x)}\\,dx = \\ln|f(x)| + C", explanation: "Reverse-chain log pattern." }, { stepNumber: 2, description: "Identify \\(f\\).", workingLatex: "f(x) = x^3 + 3x", explanation: "Denominator as \\(f\\)." }, { stepNumber: 3, description: "Differentiate \\(f\\).", workingLatex: "f'(x) = 3x^2 + 3 = 3(x^2 + 1)", explanation: "Factor out the \\(3\\) — makes the comparison with the numerator transparent." }, { stepNumber: 4, description: "Compare numerator to \\(f'(x)\\).", workingLatex: "\\text{Numerator } x^2 + 1 = \\displaystyle\\frac{1}{3}\\,f'(x)", explanation: "Short by a factor of \\(3\\)." }, { stepNumber: 5, description: "Pull out the \\(\\displaystyle\\frac{1}{3}\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{x^2 + 1}{x^3 + 3x}\\,dx = \\displaystyle\\frac{1}{3}\\displaystyle\\int \\displaystyle\\frac{3(x^2 + 1)}{x^3 + 3x}\\,dx", explanation: "Brings the numerator up to exactly \\(f'(x)\\)." }, { stepNumber: 6, description: "Apply the rule.", workingLatex: "= \\displaystyle\\frac{1}{3}\\ln|x^3 + 3x| + C", explanation: "Modulus bars stay — \\(x^3 + 3x = x(x^2 + 3)\\) changes sign at \\(x = 0\\)." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{1}{3}\\ln|x^3+3x|\\right] = \\displaystyle\\frac{1}{3}\\cdot\\displaystyle\\frac{3x^2+3}{x^3+3x} = \\displaystyle\\frac{x^2+1}{x^3+3x}\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{3}\\ln|x^3 + 3x| + C\\)." } },
  { id: "y2in4-045", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 45", difficulty: "Challenge", questionText: "Find \\[ \\int \\displaystyle\\frac{1}{2x\\sqrt{\\ln x}}\\,dx \\]", marks: 4, examStyle: true, yearCreated: 2026, tags: ["reverse chain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx", explanation: "Standard substitution. We are after a function-and-derivative pair in the integrand." }, { stepNumber: 2, description: "Why u-sub here.", workingLatex: "\\text{Spot: } \\ln x \\text{ under the root and } \\displaystyle\\frac{1}{x}\\,dx \\text{ as a co-factor.}", explanation: "The integrand has \\(\\ln x\\) inside a square root and \\(1/x\\) hidden in the denominator — perfect cue for \\(u = \\ln x\\)." }, { stepNumber: 3, description: "Choose \\(u\\).", workingLatex: "u = \\ln x", explanation: "Picking the inner composite collapses both the root and the \\(1/x\\,dx\\)." }, { stepNumber: 4, description: "Compute \\(du\\).", workingLatex: "du = \\displaystyle\\frac{1}{x}\\,dx", explanation: "Standard derivative of \\(\\ln x\\)." }, { stepNumber: 5, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{1}{2x\\sqrt{\\ln x}}\\,dx = \\displaystyle\\frac{1}{2}\\displaystyle\\int \\displaystyle\\frac{1}{\\sqrt u}\\,du = \\displaystyle\\frac{1}{2}\\displaystyle\\int u^{-\\frac{1}{2}}\\,du", explanation: "The factor of \\(\\displaystyle\\frac{1}{2}\\) comes from the \\(2\\) in \\(2x\\); the rest of \\(\\displaystyle\\frac{1}{x}\\,dx\\) becomes \\(du\\) and the \\(\\sqrt{\\ln x}\\) becomes \\(\\sqrt u\\)." }, { stepNumber: 6, description: "Integrate in \\(u\\) using the power rule.", workingLatex: "\\displaystyle\\frac{1}{2}\\displaystyle\\int u^{-\\frac{1}{2}}\\,du = \\displaystyle\\frac{1}{2}\\cdot\\displaystyle\\frac{u^{\\frac{1}{2}}}{1/2} + C = u^{\\frac{1}{2}} + C", explanation: "New index is \\(-\\displaystyle\\frac{1}{2} + 1 = \\displaystyle\\frac{1}{2}\\); divide by \\(\\displaystyle\\frac{1}{2}\\), i.e. multiply by \\(2\\); the outer \\(\\displaystyle\\frac{1}{2}\\) cancels the \\(2\\)." }, { stepNumber: 7, description: "Back-substitute.", workingLatex: "= \\sqrt{\\ln x} + C", explanation: "Replace \\(u\\) with \\(\\ln x\\)." }, { stepNumber: 8, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\sqrt{\\ln x} = \\displaystyle\\frac{1}{2\\sqrt{\\ln x}}\\cdot\\displaystyle\\frac{1}{x} = \\displaystyle\\frac{1}{2x\\sqrt{\\ln x}}\\;\\checkmark", explanation: "Two-step chain rule recovers the integrand." } ], finalAnswer: "\\(\\sqrt{\\ln x} + C\\)." } },
  { id: "y2in4-046", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 46", difficulty: "Standard", questionText: "Find \\[ \\int \\sin^3 x\\cos x\\,dx \\]", marks: 2, examStyle: false, yearCreated: 2026, tags: ["reverse chain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int f'(x)\\bigl[f(x)\\bigr]^n\\,dx = \\displaystyle\\frac{\\bigl[f(x)\\bigr]^{n+1}}{n+1} + C", explanation: "Reverse-chain power rule." }, { stepNumber: 2, description: "Choose the inner function.", workingLatex: "f(x) = \\sin x", explanation: "Pick \\(\\sin x\\) so the cube becomes \\(f^3\\); then check the remaining \\(\\cos x\\)." }, { stepNumber: 3, description: "Differentiate \\(f\\).", workingLatex: "f'(x) = \\cos x", explanation: "Standard derivative." }, { stepNumber: 4, description: "Compare co-factor to \\(f'(x)\\).", workingLatex: "\\text{Co-factor } \\cos x = f'(x)", explanation: "Exact match — clean set-up with no rescaling." }, { stepNumber: 5, description: "Apply the rule with \\(n = 3\\).", workingLatex: "\\displaystyle\\int \\sin^3 x\\cos x\\,dx = \\displaystyle\\frac{\\sin^4 x}{4} + C", explanation: "Index to \\(4\\); divide by \\(4\\)." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{\\sin^4 x}{4}\\right] = \\sin^3 x\\cdot\\cos x\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{\\sin^4 x}{4} + C\\)." } },
  { id: "y2in4-047", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 47", difficulty: "Standard", questionText: "Find \\[ \\int \\cos^5 x\\sin x\\,dx \\]", marks: 2, examStyle: false, yearCreated: 2026, tags: ["reverse chain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int f'(x)\\bigl[f(x)\\bigr]^n\\,dx = \\displaystyle\\frac{\\bigl[f(x)\\bigr]^{n+1}}{n+1} + C", explanation: "Reverse-chain power rule." }, { stepNumber: 2, description: "Choose the inner function.", workingLatex: "f(x) = \\cos x", explanation: "Pick \\(\\cos x\\) so the fifth power becomes \\(f^5\\)." }, { stepNumber: 3, description: "Differentiate \\(f\\).", workingLatex: "f'(x) = -\\sin x", explanation: "Standard derivative — minus sign is intrinsic." }, { stepNumber: 4, description: "Compare co-factor to \\(f'(x)\\).", workingLatex: "\\text{Co-factor } \\sin x = -f'(x)", explanation: "Off by one minus sign — absorb a leading minus outside the integral." }, { stepNumber: 5, description: "Rewrite with the sign exposed.", workingLatex: "\\displaystyle\\int \\cos^5 x\\sin x\\,dx = -\\displaystyle\\int \\cos^5 x(-\\sin x)\\,dx", explanation: "Two minus signs leave the value unchanged but put the integrand in clean \\(f'\\cdot f^n\\) form." }, { stepNumber: 6, description: "Apply the rule with \\(n = 5\\).", workingLatex: "= -\\displaystyle\\frac{\\cos^6 x}{6} + C", explanation: "Index to \\(6\\); divide by \\(6\\); the outer minus stays." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[-\\displaystyle\\frac{\\cos^6 x}{6}\\right] = -\\displaystyle\\frac{6\\cos^5 x\\cdot(-\\sin x)}{6} = \\cos^5 x\\sin x\\;\\checkmark", explanation: "Two minuses combine to a plus — recovers the integrand." } ], finalAnswer: "\\(-\\displaystyle\\frac{\\cos^6 x}{6} + C\\)." } },
  { id: "y2in4-048", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 48", difficulty: "Standard", questionText: "Find \\[ \\int \\displaystyle\\frac{2e^{2x}}{e^{2x} + 3}\\,dx \\]", marks: 2, examStyle: false, yearCreated: 2026, tags: ["log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{f'(x)}{f(x)}\\,dx = \\ln|f(x)| + C", explanation: "Reverse-chain log pattern." }, { stepNumber: 2, description: "Identify \\(f\\).", workingLatex: "f(x) = e^{2x} + 3", explanation: "Denominator as \\(f\\)." }, { stepNumber: 3, description: "Differentiate \\(f\\).", workingLatex: "f'(x) = 2e^{2x}", explanation: "Chain rule on \\(e^{2x}\\): the inner derivative \\(2\\) comes outside." }, { stepNumber: 4, description: "Compare numerator to \\(f'(x)\\).", workingLatex: "\\text{Numerator } 2e^{2x} = f'(x)", explanation: "Exact match — clean \\(f'/f\\) form." }, { stepNumber: 5, description: "Apply the rule.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{2e^{2x}}{e^{2x} + 3}\\,dx = \\ln(e^{2x} + 3) + C", explanation: "Since \\(e^{2x} > 0\\), the argument is \\(\\ge 3 > 0\\), and the bars can be dropped." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\ln(e^{2x} + 3) = \\displaystyle\\frac{2e^{2x}}{e^{2x} + 3}\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\ln(e^{2x} + 3) + C\\)." } },
  { id: "y2in4-049", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 49", difficulty: "Challenge", questionText: "Find \\[ \\int \\displaystyle\\frac{1}{\\left(2x + 1\\right)\\ln(2x + 1)}\\,dx \\]", marks: 4, examStyle: true, yearCreated: 2026, tags: ["log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx", explanation: "Standard \\(u\\)-substitution; we want a function and its derivative inside the integrand." }, { stepNumber: 2, description: "Why u-sub here.", workingLatex: "\\text{Spot: } \\ln(2x + 1) \\text{ and a } 1/(2x+1) \\text{ factor.}", explanation: "The integrand has \\(\\ln(2x+1)\\) in the denominator and \\(1/(2x+1)\\) as a co-factor — the natural cue for \\(u = \\ln(2x+1)\\)." }, { stepNumber: 3, description: "Choose \\(u\\).", workingLatex: "u = \\ln(2x + 1)", explanation: "Inner composite; its derivative will pick up the rest of the integrand." }, { stepNumber: 4, description: "Compute \\(du\\).", workingLatex: "du = \\displaystyle\\frac{2}{2x + 1}\\,dx \\;\\Rightarrow\\; \\displaystyle\\frac{dx}{2x + 1} = \\displaystyle\\frac{1}{2}\\,du", explanation: "Chain rule on \\(\\ln(2x+1)\\) gives \\(2/(2x+1)\\); rearranging isolates the \\(dx/(2x+1)\\) factor that actually appears in the integrand." }, { stepNumber: 5, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{1}{(2x + 1)\\ln(2x + 1)}\\,dx = \\displaystyle\\int \\displaystyle\\frac{1}{u}\\cdot\\displaystyle\\frac{1}{2}\\,du = \\displaystyle\\frac{1}{2}\\displaystyle\\int \\displaystyle\\frac{1}{u}\\,du", explanation: "Substitute \\(\\ln(2x+1) \\to u\\) and \\(dx/(2x+1) \\to \\displaystyle\\frac{1}{2}\\,du\\)." }, { stepNumber: 6, description: "Integrate in \\(u\\).", workingLatex: "\\displaystyle\\frac{1}{2}\\displaystyle\\int \\displaystyle\\frac{1}{u}\\,du = \\displaystyle\\frac{1}{2}\\ln|u| + C", explanation: "Standard antiderivative." }, { stepNumber: 7, description: "Back-substitute.", workingLatex: "= \\displaystyle\\frac{1}{2}\\ln|\\ln(2x + 1)| + C", explanation: "Modulus bars stay — \\(\\ln(2x+1) < 0\\) when \\(0 < 2x+1 < 1\\), i.e. \\(-\\displaystyle\\frac{1}{2} < x < 0\\)." }, { stepNumber: 8, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{1}{2}\\ln|\\ln(2x+1)|\\right] = \\displaystyle\\frac{1}{2}\\cdot\\displaystyle\\frac{1}{\\ln(2x+1)}\\cdot\\displaystyle\\frac{2}{2x+1} = \\displaystyle\\frac{1}{(2x+1)\\ln(2x+1)}\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{2}\\ln|\\ln(2x + 1)| + C\\)." } },
  { id: "y2in4-050", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 50", difficulty: "Challenge", questionText: "Find \\[ \\int \\displaystyle\\frac{\\sec x\\tan x}{\\sec x + 1}\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{f'(x)}{f(x)}\\,dx = \\ln|f(x)| + C", explanation: "Reverse-chain log pattern." }, { stepNumber: 2, description: "Identify \\(f\\).", workingLatex: "f(x) = \\sec x + 1", explanation: "Denominator as \\(f\\)." }, { stepNumber: 3, description: "Differentiate \\(f\\).", workingLatex: "f'(x) = \\sec x\\tan x", explanation: "Standard derivative: \\(\\displaystyle\\frac{d}{dx}\\sec x = \\sec x\\tan x\\). The constant \\(1\\) drops out." }, { stepNumber: 4, description: "Compare numerator to \\(f'(x)\\).", workingLatex: "\\text{Numerator } \\sec x\\tan x = f'(x)", explanation: "Exact match — clean \\(f'/f\\) form." }, { stepNumber: 5, description: "Apply the rule.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{\\sec x\\tan x}{\\sec x + 1}\\,dx = \\ln|\\sec x + 1| + C", explanation: "Modulus bars matter — \\(\\sec x + 1\\) can be negative (when \\(\\sec x < -1\\), i.e. on certain ranges of \\(x\\))." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\ln|\\sec x + 1| = \\displaystyle\\frac{\\sec x\\tan x}{\\sec x + 1}\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\ln|\\sec x + 1| + C\\)." } },
  // ── Mixed practice ────
  { id: "y2in4-051", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 51", difficulty: "Standard", questionText: "Find \\[ \\int x(2x^2 - 5)^4\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["reverse chain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int f'(x)\\bigl[f(x)\\bigr]^n\\,dx = \\displaystyle\\frac{\\bigl[f(x)\\bigr]^{n+1}}{n+1} + C", explanation: "Reverse-chain power rule." }, { stepNumber: 2, description: "Identify \\(f\\).", workingLatex: "f(x) = 2x^2 - 5", explanation: "Base of the power inside the bracket." }, { stepNumber: 3, description: "Differentiate \\(f\\).", workingLatex: "f'(x) = 4x", explanation: "Power rule with the leading coefficient." }, { stepNumber: 4, description: "Compare the co-factor to \\(f'(x)\\).", workingLatex: "\\text{Co-factor } x = \\displaystyle\\frac{1}{4}\\,f'(x)", explanation: "Short by a factor of \\(4\\); compensate with \\(\\displaystyle\\frac{1}{4}\\)." }, { stepNumber: 5, description: "Pull out the \\(\\displaystyle\\frac{1}{4}\\).", workingLatex: "\\displaystyle\\int x(2x^2 - 5)^4\\,dx = \\displaystyle\\frac{1}{4}\\displaystyle\\int 4x(2x^2 - 5)^4\\,dx", explanation: "Brings the co-factor up to exactly \\(f'(x)\\)." }, { stepNumber: 6, description: "Apply the rule with \\(n = 4\\).", workingLatex: "= \\displaystyle\\frac{1}{4}\\cdot\\displaystyle\\frac{(2x^2 - 5)^5}{5} + C", explanation: "Index to \\(5\\); divide by \\(5\\)." }, { stepNumber: 7, description: "Tidy.", workingLatex: "= \\displaystyle\\frac{(2x^2 - 5)^5}{20} + C", explanation: "Combine constants: \\(\\displaystyle\\frac{1}{4}\\cdot\\displaystyle\\frac{1}{5} = \\displaystyle\\frac{1}{20}\\)." }, { stepNumber: 8, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{(2x^2-5)^5}{20}\\right] = \\displaystyle\\frac{5(2x^2-5)^4\\cdot 4x}{20} = x(2x^2-5)^4\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{(2x^2 - 5)^5}{20} + C\\)." } },
  { id: "y2in4-052", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 52", difficulty: "Standard", questionText: "Find \\[ \\int \\left(x + 2\\right)\\left(x^2 + 4x\\right)^3\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["reverse chain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int f'(x)\\bigl[f(x)\\bigr]^n\\,dx = \\displaystyle\\frac{\\bigl[f(x)\\bigr]^{n+1}}{n+1} + C", explanation: "Reverse-chain power rule." }, { stepNumber: 2, description: "Identify \\(f\\).", workingLatex: "f(x) = x^2 + 4x", explanation: "Base of the cube." }, { stepNumber: 3, description: "Differentiate \\(f\\).", workingLatex: "f'(x) = 2x + 4 = 2(x + 2)", explanation: "Factoring out the \\(2\\) makes the comparison with the co-factor transparent." }, { stepNumber: 4, description: "Compare the co-factor to \\(f'(x)\\).", workingLatex: "\\text{Co-factor } x + 2 = \\displaystyle\\frac{1}{2}\\,f'(x)", explanation: "Short by a factor of \\(2\\)." }, { stepNumber: 5, description: "Pull out the \\(\\displaystyle\\frac{1}{2}\\).", workingLatex: "\\displaystyle\\int (x + 2)(x^2 + 4x)^3\\,dx = \\displaystyle\\frac{1}{2}\\displaystyle\\int 2(x + 2)(x^2 + 4x)^3\\,dx", explanation: "Brings the co-factor up to exactly \\(f'(x)\\)." }, { stepNumber: 6, description: "Apply the rule with \\(n = 3\\).", workingLatex: "= \\displaystyle\\frac{1}{2}\\cdot\\displaystyle\\frac{(x^2 + 4x)^4}{4} + C = \\displaystyle\\frac{(x^2 + 4x)^4}{8} + C", explanation: "Index to \\(4\\); divide by \\(4\\); combine with the outer \\(\\displaystyle\\frac{1}{2}\\) to get \\(\\displaystyle\\frac{1}{8}\\)." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{(x^2+4x)^4}{8}\\right] = \\displaystyle\\frac{4(x^2+4x)^3(2x+4)}{8} = (x+2)(x^2+4x)^3\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{(x^2 + 4x)^4}{8} + C\\)." } },
  { id: "y2in4-053", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 53", difficulty: "Standard", questionText: "Find \\[ \\int e^{\\cos x}\\sin x\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["reverse chain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int g'(x)\\,e^{g(x)}\\,dx = e^{g(x)} + C", explanation: "Reverse-chain exponential rule." }, { stepNumber: 2, description: "Identify the inner function \\(g\\).", workingLatex: "g(x) = \\cos x", explanation: "The exponent inside the exponential." }, { stepNumber: 3, description: "Differentiate \\(g\\).", workingLatex: "g'(x) = -\\sin x", explanation: "Standard derivative — minus sign is intrinsic." }, { stepNumber: 4, description: "Compare co-factor to \\(g'(x)\\).", workingLatex: "\\text{Co-factor } \\sin x = -g'(x)", explanation: "Off by one minus sign; absorb a leading minus outside the integral." }, { stepNumber: 5, description: "Rewrite with the sign exposed.", workingLatex: "\\displaystyle\\int e^{\\cos x}\\sin x\\,dx = -\\displaystyle\\int (-\\sin x)\\,e^{\\cos x}\\,dx", explanation: "Now in the form \\(g'(x)\\,e^{g(x)}\\) with an outer minus." }, { stepNumber: 6, description: "Apply the rule.", workingLatex: "= -e^{\\cos x} + C", explanation: "The bracketed integral is the rule's template; the outer minus stays." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[-e^{\\cos x}\\right] = -e^{\\cos x}\\cdot(-\\sin x) = e^{\\cos x}\\sin x\\;\\checkmark", explanation: "Two minuses combine to a plus — recovers the integrand." } ], finalAnswer: "\\(-e^{\\cos x} + C\\)." } },
  { id: "y2in4-054", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 54", difficulty: "Standard", questionText: "Find \\[ \\int \\displaystyle\\frac{x^2}{\\sqrt{x^3 + 1}}\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["reverse chain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int f'(x)\\bigl[f(x)\\bigr]^n\\,dx = \\displaystyle\\frac{\\bigl[f(x)\\bigr]^{n+1}}{n+1} + C", explanation: "Reverse-chain power rule (works for \\(n = -\\displaystyle\\frac{1}{2}\\) — the \\(1/\\sqrt{\\;\\cdot\\;}\\) case)." }, { stepNumber: 2, description: "Rewrite the integrand as a power.", workingLatex: "\\displaystyle\\frac{x^2}{\\sqrt{x^3 + 1}} = x^2(x^3 + 1)^{-\\frac{1}{2}}", explanation: "Surfaces the \\(f'\\cdot f^n\\) structure." }, { stepNumber: 3, description: "Identify \\(f\\) and differentiate.", workingLatex: "f(x) = x^3 + 1 \\;\\Rightarrow\\; f'(x) = 3x^2", explanation: "Base of the power; its derivative is \\(3x^2\\)." }, { stepNumber: 4, description: "Compare co-factor to \\(f'(x)\\).", workingLatex: "\\text{Co-factor } x^2 = \\displaystyle\\frac{1}{3}\\,f'(x)", explanation: "Short by a factor of \\(3\\)." }, { stepNumber: 5, description: "Pull out the \\(\\displaystyle\\frac{1}{3}\\).", workingLatex: "\\displaystyle\\int x^2(x^3 + 1)^{-\\frac{1}{2}}\\,dx = \\displaystyle\\frac{1}{3}\\displaystyle\\int 3x^2(x^3 + 1)^{-\\frac{1}{2}}\\,dx", explanation: "Brings the co-factor up to \\(f'(x)\\)." }, { stepNumber: 6, description: "Apply the rule with \\(n = -\\displaystyle\\frac{1}{2}\\).", workingLatex: "= \\displaystyle\\frac{1}{3}\\cdot\\displaystyle\\frac{(x^3 + 1)^{\\frac{1}{2}}}{1/2} + C", explanation: "New index is \\(\\displaystyle\\frac{1}{2}\\); divide by \\(\\displaystyle\\frac{1}{2}\\), i.e. multiply by \\(2\\)." }, { stepNumber: 7, description: "Tidy.", workingLatex: "= \\displaystyle\\frac{2}{3}\\sqrt{x^3 + 1} + C", explanation: "\\(\\displaystyle\\frac{1}{3}\\cdot 2 = \\displaystyle\\frac{2}{3}\\)." }, { stepNumber: 8, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{2\\sqrt{x^3+1}}{3}\\right] = \\displaystyle\\frac{2}{3}\\cdot\\displaystyle\\frac{3x^2}{2\\sqrt{x^3+1}} = \\displaystyle\\frac{x^2}{\\sqrt{x^3+1}}\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{2\\sqrt{x^3 + 1}}{3} + C\\)." } },
  { id: "y2in4-055", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 55", difficulty: "Standard", questionText: "Find \\[ \\int \\displaystyle\\frac{\\sin x}{\\cos^3 x}\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["reverse chain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int f'(x)\\bigl[f(x)\\bigr]^n\\,dx = \\displaystyle\\frac{\\bigl[f(x)\\bigr]^{n+1}}{n+1} + C", explanation: "Reverse-chain power rule — works for negative \\(n\\) as long as \\(n \\neq -1\\)." }, { stepNumber: 2, description: "Rewrite the integrand as a power.", workingLatex: "\\displaystyle\\frac{\\sin x}{\\cos^3 x} = \\sin x\\cdot(\\cos x)^{-3}", explanation: "Surfaces the \\(f'\\cdot f^n\\) structure with \\(n = -3\\)." }, { stepNumber: 3, description: "Choose \\(f\\) and differentiate.", workingLatex: "f(x) = \\cos x \\;\\Rightarrow\\; f'(x) = -\\sin x", explanation: "Base of the power; its derivative is \\(-\\sin x\\)." }, { stepNumber: 4, description: "Compare co-factor to \\(f'(x)\\).", workingLatex: "\\text{Co-factor } \\sin x = -f'(x)", explanation: "Off by a minus." }, { stepNumber: 5, description: "Rewrite with the sign exposed.", workingLatex: "\\displaystyle\\int \\sin x(\\cos x)^{-3}\\,dx = -\\displaystyle\\int (-\\sin x)(\\cos x)^{-3}\\,dx", explanation: "Now in clean \\(f'\\cdot f^n\\) form with an outer minus." }, { stepNumber: 6, description: "Apply the rule with \\(n = -3\\).", workingLatex: "= -\\displaystyle\\frac{(\\cos x)^{-2}}{-2} + C", explanation: "New index is \\(-3 + 1 = -2\\); divide by \\(-2\\)." }, { stepNumber: 7, description: "Tidy.", workingLatex: "= \\displaystyle\\frac{1}{2\\cos^2 x} + C = \\displaystyle\\frac{\\sec^2 x}{2} + C", explanation: "The outer minus and the \\(-2\\) downstairs combine to \\(\\displaystyle\\frac{1}{2}\\); rewrite \\((\\cos x)^{-2}\\) as \\(\\sec^2 x\\)." }, { stepNumber: 8, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{\\sec^2 x}{2}\\right] = \\displaystyle\\frac{2\\sec x\\cdot\\sec x\\tan x}{2} = \\sec^2 x\\tan x = \\displaystyle\\frac{\\sin x}{\\cos^3 x}\\;\\checkmark", explanation: "Using \\(\\sec^2 x\\tan x = \\displaystyle\\frac{1}{\\cos^2 x}\\cdot\\displaystyle\\frac{\\sin x}{\\cos x} = \\displaystyle\\frac{\\sin x}{\\cos^3 x}\\); recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{2\\cos^2 x} + C = \\displaystyle\\frac{\\sec^2 x}{2} + C\\)." } },
  { id: "y2in4-056", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 56", difficulty: "Challenge", questionText: "Find \\[ \\int \\displaystyle\\frac{3}{x\\ln^2 x}\\,dx \\]", marks: 4, examStyle: true, yearCreated: 2026, tags: ["reverse chain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx", explanation: "Standard \\(u\\)-substitution." }, { stepNumber: 2, description: "Why u-sub here.", workingLatex: "\\text{Spot: } \\ln^2 x \\text{ in the denominator and } \\displaystyle\\frac{1}{x}\\,dx \\text{ as a co-factor.}", explanation: "The composite \\(\\ln x\\) appears squared in the denominator, and its derivative \\(1/x\\) appears outside — perfect for \\(u = \\ln x\\)." }, { stepNumber: 3, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = \\ln x \\;\\Rightarrow\\; du = \\displaystyle\\frac{1}{x}\\,dx", explanation: "Inner composite; both pieces fold into \\(u\\) and \\(du\\)." }, { stepNumber: 4, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{3}{x\\ln^2 x}\\,dx = 3\\displaystyle\\int \\displaystyle\\frac{1}{u^2}\\,du = 3\\displaystyle\\int u^{-2}\\,du", explanation: "Replace \\(\\ln x \\to u\\) and \\(\\displaystyle\\frac{1}{x}\\,dx \\to du\\); the constant \\(3\\) pulls out front." }, { stepNumber: 5, description: "Integrate using the power rule.", workingLatex: "3\\cdot\\displaystyle\\frac{u^{-1}}{-1} + C = -\\displaystyle\\frac{3}{u} + C", explanation: "New index is \\(-1\\); divide by \\(-1\\)." }, { stepNumber: 6, description: "Back-substitute.", workingLatex: "= -\\displaystyle\\frac{3}{\\ln x} + C", explanation: "Replace \\(u\\) with \\(\\ln x\\)." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[-\\displaystyle\\frac{3}{\\ln x}\\right] = -3\\cdot\\displaystyle\\frac{-1}{(\\ln x)^2}\\cdot\\displaystyle\\frac{1}{x} = \\displaystyle\\frac{3}{x\\ln^2 x}\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(-\\displaystyle\\frac{3}{\\ln x} + C\\)." } },
  { id: "y2in4-057", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 57", difficulty: "Standard", questionText: "Find \\[ \\int \\csc^2 x\\cot x\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["reverse chain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx", explanation: "Standard substitution." }, { stepNumber: 2, description: "Why u-sub here.", workingLatex: "\\text{Spot: } \\cot x \\text{ together with } \\csc^2 x\\,dx — \\text{ a function and (negative) its derivative.}", explanation: "Picking \\(\\cot x\\) as \\(u\\) sweeps the \\(\\csc^2 x\\,dx\\) factor (up to a minus sign) into \\(du\\)." }, { stepNumber: 3, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = \\cot x \\;\\Rightarrow\\; du = -\\csc^2 x\\,dx", explanation: "Standard derivative: \\(\\displaystyle\\frac{d}{dx}\\cot x = -\\csc^2 x\\). Hence \\(\\csc^2 x\\,dx = -du\\)." }, { stepNumber: 4, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\csc^2 x\\cot x\\,dx = \\displaystyle\\int u\\cdot(-du) = -\\displaystyle\\int u\\,du", explanation: "Substitute \\(\\cot x \\to u\\) and \\(\\csc^2 x\\,dx \\to -du\\)." }, { stepNumber: 5, description: "Integrate in \\(u\\).", workingLatex: "-\\displaystyle\\int u\\,du = -\\displaystyle\\frac{u^2}{2} + C", explanation: "Power rule: \\(\\int u\\,du = u^2/2\\)." }, { stepNumber: 6, description: "Back-substitute.", workingLatex: "= -\\displaystyle\\frac{\\cot^2 x}{2} + C", explanation: "Replace \\(u\\) with \\(\\cot x\\)." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[-\\displaystyle\\frac{\\cot^2 x}{2}\\right] = -\\displaystyle\\frac{2\\cot x\\cdot(-\\csc^2 x)}{2} = \\csc^2 x\\cot x\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(-\\displaystyle\\frac{\\cot^2 x}{2} + C\\)." } },
  { id: "y2in4-058", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 58", difficulty: "Standard", questionText: "Find \\[ \\int \\displaystyle\\frac{2x - 1}{x^2 - x + 4}\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{f'(x)}{f(x)}\\,dx = \\ln|f(x)| + C", explanation: "Reverse-chain log pattern." }, { stepNumber: 2, description: "Identify \\(f\\).", workingLatex: "f(x) = x^2 - x + 4", explanation: "Denominator as \\(f\\)." }, { stepNumber: 3, description: "Differentiate \\(f\\).", workingLatex: "f'(x) = 2x - 1", explanation: "Term-by-term differentiation." }, { stepNumber: 4, description: "Compare numerator to \\(f'(x)\\).", workingLatex: "\\text{Numerator } 2x - 1 = f'(x)", explanation: "Exact match — clean \\(f'/f\\) form." }, { stepNumber: 5, description: "Apply the rule.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{2x - 1}{x^2 - x + 4}\\,dx = \\ln|x^2 - x + 4| + C", explanation: "Direct application." }, { stepNumber: 6, description: "Drop the modulus bars.", workingLatex: "x^2 - x + 4 = \\left(x - \\displaystyle\\frac{1}{2}\\right)^2 + \\displaystyle\\frac{15}{4} > 0 \\;\\Rightarrow\\; = \\ln(x^2 - x + 4) + C", explanation: "Completing the square shows the quadratic is always positive; bars are redundant." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\ln(x^2 - x + 4) = \\displaystyle\\frac{2x - 1}{x^2 - x + 4}\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\ln(x^2 - x + 4) + C\\)." } },
  { id: "y2in4-059", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 59", difficulty: "Standard", questionText: "Find \\[ \\int \\displaystyle\\frac{\\cos x - \\sin x}{\\sin x + \\cos x}\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{f'(x)}{f(x)}\\,dx = \\ln|f(x)| + C", explanation: "Reverse-chain log pattern." }, { stepNumber: 2, description: "Identify \\(f\\).", workingLatex: "f(x) = \\sin x + \\cos x", explanation: "Denominator as \\(f\\)." }, { stepNumber: 3, description: "Differentiate \\(f\\).", workingLatex: "f'(x) = \\cos x - \\sin x", explanation: "\\(\\displaystyle\\frac{d}{dx}\\sin x = \\cos x\\); \\(\\displaystyle\\frac{d}{dx}\\cos x = -\\sin x\\)." }, { stepNumber: 4, description: "Compare numerator to \\(f'(x)\\).", workingLatex: "\\text{Numerator } \\cos x - \\sin x = f'(x)", explanation: "Exact match — clean \\(f'/f\\) form." }, { stepNumber: 5, description: "Apply the rule.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{\\cos x - \\sin x}{\\sin x + \\cos x}\\,dx = \\ln|\\sin x + \\cos x| + C", explanation: "Modulus bars are required — \\(\\sin x + \\cos x = \\sqrt 2\\,\\sin(x + \\pi/4)\\) changes sign periodically." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\ln|\\sin x + \\cos x| = \\displaystyle\\frac{\\cos x - \\sin x}{\\sin x + \\cos x}\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\ln|\\sin x + \\cos x| + C\\)." } },
  { id: "y2in4-060", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 60", difficulty: "Standard", questionText: "Find \\[ \\int \\displaystyle\\frac{\\sec x\\tan x}{\\sec x - 1}\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{f'(x)}{f(x)}\\,dx = \\ln|f(x)| + C", explanation: "Reverse-chain log pattern." }, { stepNumber: 2, description: "Identify \\(f\\).", workingLatex: "f(x) = \\sec x - 1", explanation: "Denominator as \\(f\\)." }, { stepNumber: 3, description: "Differentiate \\(f\\).", workingLatex: "f'(x) = \\sec x\\tan x", explanation: "\\(\\displaystyle\\frac{d}{dx}\\sec x = \\sec x\\tan x\\); the constant \\(-1\\) drops out." }, { stepNumber: 4, description: "Compare numerator to \\(f'(x)\\).", workingLatex: "\\text{Numerator } \\sec x\\tan x = f'(x)", explanation: "Exact match — clean \\(f'/f\\) form." }, { stepNumber: 5, description: "Apply the rule.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{\\sec x\\tan x}{\\sec x - 1}\\,dx = \\ln|\\sec x - 1| + C", explanation: "Modulus bars stay — \\(\\sec x - 1\\) is negative when \\(\\sec x < 1\\), i.e. on parts of the domain." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\ln|\\sec x - 1| = \\displaystyle\\frac{\\sec x\\tan x}{\\sec x - 1}\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\ln|\\sec x - 1| + C\\)." } },
  // ── Applied / area ────
  { id: "y2in4-061", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 61", difficulty: "Standard", questionText: "Find the area under \\(y = \\displaystyle\\frac{x}{x^2 + 1}\\) from \\(x = 0\\) to \\(x = 2\\), i.e. evaluate \\[ \\int_0^2 \\displaystyle\\frac{x}{x^2 + 1}\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["area"], workedSolution: { steps: [ { stepNumber: 1, description: "Set up the area integral.", workingLatex: "\\text{Area} = \\displaystyle\\int_0^2 \\displaystyle\\frac{x}{x^2 + 1}\\,dx", explanation: "On \\([0, 2]\\), \\(x \\ge 0\\) and \\(x^2 + 1 > 0\\), so \\(y \\ge 0\\) throughout — the area equals the integral (no sign flips needed)." }, { stepNumber: 2, description: "State the rule used.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{f'(x)}{f(x)}\\,dx = \\ln|f(x)| + C", explanation: "Reverse-chain log pattern." }, { stepNumber: 3, description: "Identify \\(f\\) and differentiate.", workingLatex: "f(x) = x^2 + 1 \\;\\Rightarrow\\; f'(x) = 2x", explanation: "Denominator as \\(f\\); its derivative is \\(2x\\)." }, { stepNumber: 4, description: "Compare numerator to \\(f'(x)\\) and rescale.", workingLatex: "\\text{Numerator } x = \\displaystyle\\frac{1}{2}\\,f'(x)", explanation: "Short by a factor of \\(2\\); compensate with \\(\\displaystyle\\frac{1}{2}\\)." }, { stepNumber: 5, description: "Find the antiderivative.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{x}{x^2 + 1}\\,dx = \\displaystyle\\frac{1}{2}\\ln(x^2 + 1) + C", explanation: "Apply \\(f'/f\\) rule; bars drop since \\(x^2 + 1 > 0\\)." }, { stepNumber: 6, description: "Apply the limits.", workingLatex: "\\left[\\displaystyle\\frac{1}{2}\\ln(x^2 + 1)\\right]_0^2 = \\displaystyle\\frac{1}{2}\\ln 5 - \\displaystyle\\frac{1}{2}\\ln 1 = \\displaystyle\\frac{1}{2}\\ln 5", explanation: "\\(\\ln 1 = 0\\); positive answer as expected for an area." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{2}\\ln 5\\)." } },
  { id: "y2in4-062", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 62", difficulty: "Standard", questionText: "Find the area under \\(y = xe^{x^2}\\) from 0 to 1.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["area"], workedSolution: { steps: [ { stepNumber: 1, description: "Set up the area integral.", workingLatex: "\\text{Area} = \\displaystyle\\int_0^1 xe^{x^2}\\,dx", explanation: "On \\([0, 1]\\), both \\(x \\ge 0\\) and \\(e^{x^2} > 0\\), so the integrand is non-negative — the area equals the integral." }, { stepNumber: 2, description: "State the rule used.", workingLatex: "\\displaystyle\\int g'(x)\\,e^{g(x)}\\,dx = e^{g(x)} + C", explanation: "Reverse-chain exponential rule." }, { stepNumber: 3, description: "Identify \\(g\\) and rescale.", workingLatex: "g = x^2, \\; g' = 2x, \\;\\Rightarrow\\; x = \\displaystyle\\frac{1}{2}\\,g'(x)", explanation: "Compensate with \\(\\displaystyle\\frac{1}{2}\\) outside." }, { stepNumber: 4, description: "Find the antiderivative.", workingLatex: "\\displaystyle\\int xe^{x^2}\\,dx = \\displaystyle\\frac{e^{x^2}}{2} + C", explanation: "Apply the rule." }, { stepNumber: 5, description: "Apply the limits.", workingLatex: "\\left[\\displaystyle\\frac{e^{x^2}}{2}\\right]_0^1 = \\displaystyle\\frac{e}{2} - \\displaystyle\\frac{1}{2}", explanation: "\\(e^0 = 1\\)." }, { stepNumber: 6, description: "Tidy.", workingLatex: "= \\displaystyle\\frac{e - 1}{2}", explanation: "Positive (\\(e > 1\\)) as expected for an area." } ], finalAnswer: "\\(\\displaystyle\\frac{e - 1}{2}\\)." } },
  { id: "y2in4-063", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 63", difficulty: "Challenge", questionText: "Find \\[ \\int \\displaystyle\\frac{e^{2x}}{\\sqrt{e^{2x} + 4}}\\,dx \\]", marks: 4, examStyle: true, yearCreated: 2026, tags: ["reverse chain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int f'(x)\\bigl[f(x)\\bigr]^n\\,dx = \\displaystyle\\frac{\\bigl[f(x)\\bigr]^{n+1}}{n+1} + C", explanation: "Reverse-chain power rule with \\(n = -\\displaystyle\\frac{1}{2}\\)." }, { stepNumber: 2, description: "Rewrite the integrand as a power.", workingLatex: "\\displaystyle\\frac{e^{2x}}{\\sqrt{e^{2x} + 4}} = e^{2x}(e^{2x} + 4)^{-\\frac{1}{2}}", explanation: "Brings out the \\(f'\\cdot f^n\\) structure." }, { stepNumber: 3, description: "Identify \\(f\\) and differentiate.", workingLatex: "f(x) = e^{2x} + 4 \\;\\Rightarrow\\; f'(x) = 2e^{2x}", explanation: "Chain rule on \\(e^{2x}\\) gives \\(2e^{2x}\\); the \\(+4\\) drops out." }, { stepNumber: 4, description: "Compare co-factor to \\(f'(x)\\).", workingLatex: "\\text{Co-factor } e^{2x} = \\displaystyle\\frac{1}{2}\\,f'(x)", explanation: "Short by a factor of \\(2\\)." }, { stepNumber: 5, description: "Pull out the \\(\\displaystyle\\frac{1}{2}\\).", workingLatex: "\\displaystyle\\int e^{2x}(e^{2x} + 4)^{-\\frac{1}{2}}\\,dx = \\displaystyle\\frac{1}{2}\\displaystyle\\int 2e^{2x}(e^{2x} + 4)^{-\\frac{1}{2}}\\,dx", explanation: "Brings the co-factor up to \\(f'(x)\\)." }, { stepNumber: 6, description: "Apply the rule with \\(n = -\\displaystyle\\frac{1}{2}\\).", workingLatex: "= \\displaystyle\\frac{1}{2}\\cdot\\displaystyle\\frac{(e^{2x} + 4)^{\\frac{1}{2}}}{1/2} + C", explanation: "New index is \\(\\displaystyle\\frac{1}{2}\\); divide by \\(\\displaystyle\\frac{1}{2}\\)." }, { stepNumber: 7, description: "Tidy.", workingLatex: "= \\sqrt{e^{2x} + 4} + C", explanation: "The \\(\\displaystyle\\frac{1}{2}\\) outside cancels with the factor of \\(2\\) from the rule." }, { stepNumber: 8, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\sqrt{e^{2x} + 4} = \\displaystyle\\frac{2e^{2x}}{2\\sqrt{e^{2x} + 4}} = \\displaystyle\\frac{e^{2x}}{\\sqrt{e^{2x} + 4}}\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\sqrt{e^{2x} + 4} + C\\)." } },
  { id: "y2in4-064", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 64", difficulty: "Standard", questionText: "Find \\[ \\int \\left(3x^2 + 2x\\right)\\left(x^3 + x^2\\right)^5\\,dx \\]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["reverse chain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int f'(x)\\bigl[f(x)\\bigr]^n\\,dx = \\displaystyle\\frac{\\bigl[f(x)\\bigr]^{n+1}}{n+1} + C", explanation: "Reverse-chain power rule." }, { stepNumber: 2, description: "Identify \\(f\\).", workingLatex: "f(x) = x^3 + x^2", explanation: "Base of the fifth power." }, { stepNumber: 3, description: "Differentiate \\(f\\).", workingLatex: "f'(x) = 3x^2 + 2x", explanation: "Term-by-term differentiation." }, { stepNumber: 4, description: "Compare co-factor to \\(f'(x)\\).", workingLatex: "\\text{Co-factor } 3x^2 + 2x = f'(x)", explanation: "Exact match — clean \\(f'\\cdot f^n\\) form with no rescaling." }, { stepNumber: 5, description: "Apply the rule with \\(n = 5\\).", workingLatex: "\\displaystyle\\int (3x^2 + 2x)(x^3 + x^2)^5\\,dx = \\displaystyle\\frac{(x^3 + x^2)^6}{6} + C", explanation: "Index to \\(6\\); divide by \\(6\\)." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{(x^3+x^2)^6}{6}\\right] = (x^3+x^2)^5(3x^2+2x)\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{(x^3 + x^2)^6}{6} + C\\)." } },
  { id: "y2in4-065", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 65", difficulty: "Challenge", questionText: "Find \\[ \\int 2\\sin x\\cos x\\sqrt{1 + \\sin^2 x}\\,dx \\]", marks: 4, examStyle: true, yearCreated: 2026, tags: ["reverse chain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx", explanation: "Standard \\(u\\)-substitution." }, { stepNumber: 2, description: "Why u-sub here.", workingLatex: "\\text{Spot: } 1 + \\sin^2 x \\text{ under the root and } 2\\sin x\\cos x \\text{ in front.}", explanation: "The derivative of \\(1 + \\sin^2 x\\) is exactly \\(2\\sin x\\cos x\\) by the chain rule — that is the front factor in the integrand. Textbook substitution set-up." }, { stepNumber: 3, description: "Choose \\(u\\).", workingLatex: "u = 1 + \\sin^2 x", explanation: "Take the inner content of the root as \\(u\\)." }, { stepNumber: 4, description: "Compute \\(du\\).", workingLatex: "du = 2\\sin x\\cos x\\,dx", explanation: "By the chain rule: \\(\\displaystyle\\frac{d}{dx}(\\sin^2 x) = 2\\sin x\\cos x\\). Exactly the front factor — no rescaling required." }, { stepNumber: 5, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int 2\\sin x\\cos x\\sqrt{1 + \\sin^2 x}\\,dx = \\displaystyle\\int \\sqrt u\\,du = \\displaystyle\\int u^{\\frac{1}{2}}\\,du", explanation: "All three pieces — the root, the front factor, and \\(dx\\) — collapse cleanly into \\(u^{1/2}\\,du\\)." }, { stepNumber: 6, description: "Integrate in \\(u\\).", workingLatex: "= \\displaystyle\\frac{u^{\\frac{3}{2}}}{3/2} + C = \\displaystyle\\frac{2}{3}u^{\\frac{3}{2}} + C", explanation: "New index is \\(\\displaystyle\\frac{3}{2}\\); divide by \\(\\displaystyle\\frac{3}{2}\\), i.e. multiply by \\(\\displaystyle\\frac{2}{3}\\)." }, { stepNumber: 7, description: "Back-substitute.", workingLatex: "= \\displaystyle\\frac{2}{3}(1 + \\sin^2 x)^{\\frac{3}{2}} + C", explanation: "Replace \\(u\\) with its definition." }, { stepNumber: 8, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{2}{3}(1+\\sin^2 x)^{3/2}\\right] = \\displaystyle\\frac{2}{3}\\cdot\\displaystyle\\frac{3}{2}(1+\\sin^2 x)^{1/2}(2\\sin x\\cos x) = 2\\sin x\\cos x\\sqrt{1+\\sin^2 x}\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{2}{3}(1 + \\sin^2 x)^{\\frac{3}{2}} + C\\)." } },
  { id: "y2in4-066", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 66", difficulty: "Challenge", questionText: "Find \\[ \\int \\displaystyle\\frac{1}{x\\ln x\\ln(\\ln x)}\\,dx \\]", marks: 5, examStyle: true, yearCreated: 2026, tags: ["reverse chain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx", explanation: "Standard \\(u\\)-substitution. Triply-nested logs make this a substitution problem rather than a direct rule application." }, { stepNumber: 2, description: "Why u-sub here.", workingLatex: "\\text{Spot three nested layers: } \\ln(\\ln x), \\ln x, \\text{ and a } \\displaystyle\\frac{1}{x}\\,dx \\text{ co-factor.}", explanation: "The structure is exactly what \\(u = \\ln(\\ln x)\\) needs — its derivative collapses both inner layers at once." }, { stepNumber: 3, description: "Choose \\(u\\).", workingLatex: "u = \\ln(\\ln x)", explanation: "Take the outermost composite; its derivative will sweep the remaining \\(1/(x\\ln x)\\,dx\\) into \\(du\\)." }, { stepNumber: 4, description: "Compute \\(du\\).", workingLatex: "du = \\displaystyle\\frac{1}{\\ln x}\\cdot\\displaystyle\\frac{1}{x}\\,dx = \\displaystyle\\frac{1}{x\\ln x}\\,dx", explanation: "Two nested chain-rule applications: \\(\\displaystyle\\frac{d}{dx}\\ln(\\ln x) = \\displaystyle\\frac{1}{\\ln x}\\cdot\\displaystyle\\frac{1}{x}\\). A common slip is to stop after only one differentiation." }, { stepNumber: 5, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{1}{x\\ln x\\ln(\\ln x)}\\,dx = \\displaystyle\\int \\displaystyle\\frac{1}{\\ln(\\ln x)}\\cdot\\displaystyle\\frac{1}{x\\ln x}\\,dx = \\displaystyle\\int \\displaystyle\\frac{1}{u}\\,du", explanation: "The triply-nested mess becomes the simplest possible log integral." }, { stepNumber: 6, description: "Integrate in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{1}{u}\\,du = \\ln|u| + C", explanation: "Standard antiderivative." }, { stepNumber: 7, description: "Back-substitute.", workingLatex: "= \\ln|\\ln(\\ln x)| + C", explanation: "Triply-nested log antiderivative — defined for \\(x > e\\) where all the inner logs are well-defined and non-zero." }, { stepNumber: 8, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\ln|\\ln(\\ln x)| = \\displaystyle\\frac{1}{\\ln(\\ln x)}\\cdot\\displaystyle\\frac{1}{\\ln x}\\cdot\\displaystyle\\frac{1}{x} = \\displaystyle\\frac{1}{x\\ln x\\ln(\\ln x)}\\;\\checkmark", explanation: "Three nested chain-rule applications recover the integrand exactly." } ], finalAnswer: "\\(\\ln|\\ln(\\ln x)| + C\\)." } },
  { id: "y2in4-067", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 67", difficulty: "Standard", questionText: "Find \\[ \\int \\displaystyle\\frac{3e^{3x}}{e^{3x} - 4}\\,dx \\]", marks: 2, examStyle: false, yearCreated: 2026, tags: ["log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{f'(x)}{f(x)}\\,dx = \\ln|f(x)| + C", explanation: "Reverse-chain log pattern." }, { stepNumber: 2, description: "Identify \\(f\\).", workingLatex: "f(x) = e^{3x} - 4", explanation: "Denominator as \\(f\\)." }, { stepNumber: 3, description: "Differentiate \\(f\\).", workingLatex: "f'(x) = 3e^{3x}", explanation: "Chain rule on \\(e^{3x}\\): the inner derivative \\(3\\) comes outside." }, { stepNumber: 4, description: "Compare numerator to \\(f'(x)\\).", workingLatex: "\\text{Numerator } 3e^{3x} = f'(x)", explanation: "Exact match — clean \\(f'/f\\) form." }, { stepNumber: 5, description: "Apply the rule.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{3e^{3x}}{e^{3x} - 4}\\,dx = \\ln|e^{3x} - 4| + C", explanation: "Modulus bars stay — \\(e^{3x} - 4 < 0\\) for \\(x < \\displaystyle\\frac{1}{3}\\ln 4\\)." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\ln|e^{3x} - 4| = \\displaystyle\\frac{3e^{3x}}{e^{3x} - 4}\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\ln|e^{3x} - 4| + C\\)." } },
  { id: "y2in4-068", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 68", difficulty: "Challenge", questionText: "Find \\[ \\int \\displaystyle\\frac{\\sin 2x}{1 + \\cos^2 x}\\,dx \\]", marks: 4, examStyle: true, yearCreated: 2026, tags: ["log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{f'(x)}{f(x)}\\,dx = \\ln|f(x)| + C", explanation: "Reverse-chain log pattern." }, { stepNumber: 2, description: "Identify \\(f\\).", workingLatex: "f(x) = 1 + \\cos^2 x", explanation: "Denominator as \\(f\\)." }, { stepNumber: 3, description: "Differentiate \\(f\\) using the chain rule.", workingLatex: "f'(x) = 2\\cos x\\cdot(-\\sin x) = -2\\sin x\\cos x", explanation: "Chain rule on \\(\\cos^2 x\\): outer power gives \\(2\\cos x\\), inner derivative gives \\(-\\sin x\\); the \\(1\\) drops out." }, { stepNumber: 4, description: "Simplify using the double-angle identity.", workingLatex: "f'(x) = -2\\sin x\\cos x = -\\sin 2x", explanation: "Using \\(2\\sin x\\cos x = \\sin 2x\\); this is what makes the numerator visible." }, { stepNumber: 5, description: "Compare numerator to \\(f'(x)\\).", workingLatex: "\\text{Numerator } \\sin 2x = -f'(x)", explanation: "Off by one minus sign; absorb a leading minus outside the integral." }, { stepNumber: 6, description: "Rewrite the integral with the matching numerator.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{\\sin 2x}{1 + \\cos^2 x}\\,dx = -\\displaystyle\\int \\displaystyle\\frac{-\\sin 2x}{1 + \\cos^2 x}\\,dx", explanation: "Now in clean \\(f'/f\\) form with an outer minus." }, { stepNumber: 7, description: "Apply the rule.", workingLatex: "= -\\ln|1 + \\cos^2 x| + C = -\\ln(1 + \\cos^2 x) + C", explanation: "\\(1 + \\cos^2 x \\ge 1 > 0\\), so the bars can be dropped." }, { stepNumber: 8, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[-\\ln(1+\\cos^2 x)\\right] = -\\displaystyle\\frac{-2\\sin x\\cos x}{1+\\cos^2 x} = \\displaystyle\\frac{\\sin 2x}{1+\\cos^2 x}\\;\\checkmark", explanation: "Two minuses combine to a plus — recovers the integrand." } ], finalAnswer: "\\(-\\ln(1 + \\cos^2 x) + C\\)." } },
  { id: "y2in4-069", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 69", difficulty: "Challenge", questionText: "Find \\[ \\int \\sin 2x\\,e^{\\sin^2 x}\\,dx \\]", marks: 4, examStyle: true, yearCreated: 2026, tags: ["reverse chain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rule used.", workingLatex: "\\displaystyle\\int g'(x)\\,e^{g(x)}\\,dx = e^{g(x)} + C", explanation: "Reverse-chain exponential rule." }, { stepNumber: 2, description: "Identify the inner function \\(g\\).", workingLatex: "g(x) = \\sin^2 x", explanation: "The exponent inside the exponential." }, { stepNumber: 3, description: "Differentiate \\(g\\) using the chain rule.", workingLatex: "g'(x) = 2\\sin x\\cos x", explanation: "Chain rule on \\(\\sin^2 x\\): outer power gives \\(2\\sin x\\), inner derivative gives \\(\\cos x\\)." }, { stepNumber: 4, description: "Apply the double-angle identity.", workingLatex: "g'(x) = 2\\sin x\\cos x = \\sin 2x", explanation: "Using \\(2\\sin x\\cos x = \\sin 2x\\) — this is exactly the front factor in the integrand." }, { stepNumber: 5, description: "Compare co-factor to \\(g'(x)\\).", workingLatex: "\\text{Co-factor } \\sin 2x = g'(x)", explanation: "Exact match — no rescaling needed." }, { stepNumber: 6, description: "Apply the rule.", workingLatex: "\\displaystyle\\int \\sin 2x\\,e^{\\sin^2 x}\\,dx = e^{\\sin^2 x} + C", explanation: "Direct application." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[e^{\\sin^2 x}\\right] = e^{\\sin^2 x}\\cdot 2\\sin x\\cos x = e^{\\sin^2 x}\\sin 2x\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(e^{\\sin^2 x} + C\\)." } },
  { id: "y2in4-070", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 70", difficulty: "Challenge", questionText: "Find \\[ \\int \\displaystyle\\frac{\\arctan x}{1 + x^2}\\,dx \\]", marks: 4, examStyle: true, yearCreated: 2026, tags: ["reverse chain"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx", explanation: "Standard \\(u\\)-substitution." }, { stepNumber: 2, description: "Why u-sub here.", workingLatex: "\\text{Spot: } \\arctan x \\text{ and its derivative } \\displaystyle\\frac{1}{1+x^2} \\text{ both appear.}", explanation: "Function-and-derivative pairing — exactly the cue for substitution." }, { stepNumber: 3, description: "Choose \\(u\\).", workingLatex: "u = \\arctan x", explanation: "The composite function in the numerator." }, { stepNumber: 4, description: "Compute \\(du\\).", workingLatex: "du = \\displaystyle\\frac{1}{1 + x^2}\\,dx", explanation: "Standard derivative of \\(\\arctan x\\) — exactly the denominator factor in the integrand." }, { stepNumber: 5, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{\\arctan x}{1 + x^2}\\,dx = \\displaystyle\\int u\\,du", explanation: "The integrand collapses to a simple power of \\(u\\)." }, { stepNumber: 6, description: "Integrate in \\(u\\).", workingLatex: "\\displaystyle\\int u\\,du = \\displaystyle\\frac{u^2}{2} + C", explanation: "Power rule." }, { stepNumber: 7, description: "Back-substitute.", workingLatex: "= \\displaystyle\\frac{(\\arctan x)^2}{2} + C", explanation: "Replace \\(u\\) with \\(\\arctan x\\)." }, { stepNumber: 8, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{(\\arctan x)^2}{2}\\right] = \\arctan x\\cdot\\displaystyle\\frac{1}{1 + x^2}\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{(\\arctan x)^2}{2} + C\\)." } },
  { id: "y2in4-071", topicRef: "y2in4", topicTitle: "Reverse Chain Rule 71", difficulty: "Challenge", questionText: "Find \\[ \\int \\displaystyle\\frac{1}{\\sqrt{1 - x^2}\\arcsin x}\\,dx \\]", marks: 4, examStyle: true, yearCreated: 2026, tags: ["log"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx", explanation: "Standard \\(u\\)-substitution." }, { stepNumber: 2, description: "Why u-sub here.", workingLatex: "\\text{Spot: } \\arcsin x \\text{ in the denominator and } \\displaystyle\\frac{1}{\\sqrt{1-x^2}}\\,dx \\text{ as the rest.}", explanation: "The integrand has \\(\\arcsin x\\) in one place and the derivative of \\(\\arcsin x\\) — namely \\(1/\\sqrt{1-x^2}\\) — sitting alongside as \\(dx\\). Textbook substitution set-up." }, { stepNumber: 3, description: "Choose \\(u\\).", workingLatex: "u = \\arcsin x", explanation: "Inner composite function." }, { stepNumber: 4, description: "Compute \\(du\\).", workingLatex: "du = \\displaystyle\\frac{1}{\\sqrt{1 - x^2}}\\,dx", explanation: "Standard derivative of \\(\\arcsin x\\). The factor that was sitting in the denominator (with \\(dx\\)) becomes exactly \\(du\\)." }, { stepNumber: 5, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{1}{\\sqrt{1 - x^2}\\arcsin x}\\,dx = \\displaystyle\\int \\displaystyle\\frac{1}{\\arcsin x}\\cdot\\displaystyle\\frac{1}{\\sqrt{1-x^2}}\\,dx = \\displaystyle\\int \\displaystyle\\frac{1}{u}\\,du", explanation: "The integrand collapses to the standard \\(1/u\\) form." }, { stepNumber: 6, description: "Integrate in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{1}{u}\\,du = \\ln|u| + C", explanation: "Standard antiderivative." }, { stepNumber: 7, description: "Back-substitute.", workingLatex: "= \\ln|\\arcsin x| + C", explanation: "Replace \\(u\\) with \\(\\arcsin x\\). Modulus bars stay — \\(\\arcsin x < 0\\) for \\(-1 < x < 0\\)." }, { stepNumber: 8, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\ln|\\arcsin x| = \\displaystyle\\frac{1}{\\arcsin x}\\cdot\\displaystyle\\frac{1}{\\sqrt{1 - x^2}} = \\displaystyle\\frac{1}{\\sqrt{1 - x^2}\\arcsin x}\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\ln|\\arcsin x| + C\\)." } },
];
